import React, { useEffect, useState, Suspense } from "react";
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
  useLocation,
} from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import ErrorBoundary from "./components/common/ErrorBoundary";
import TopProgressBar from "./components/common/TopProgressBar";
import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
import { AppProvider } from "./contexts/AppContext";
import { ThemeProvider } from "./contexts/ThemeContext";
import { AuthProvider } from "./contexts/AuthContext";
import "./index.css";
import { LoginPage } from "./components/auth/LoginPage";
import { ResetPasswordPage } from "./components/auth/ResetPasswordPage";
import { ProtectedRoute } from "./components/auth/ProtectedRoute";
import { RoleBasedRedirect } from "./components/auth/RoleBasedRedirect";
import { useAppContext } from "./contexts/AppContext";
import { BottomNav, Nav } from "./components/layout";
import { ShopLayout } from "./components/layout/ShopLayout";
import Dashboard from "./components/dashboard/Dashboard";
import RepoErrorPanel from "./components/common/RepoErrorPanel";
import { lazyImport } from "./utils/lazyImport";
import { canAccessInventorySection } from "./utils/inventoryAccess";
import { canDo } from "./utils/permissions";

// Lazy load large components for code splitting
// Lazy load large components for code splitting
const InventoryManager = lazyImport(
  () => import("./components/inventory/InventoryManager")
);

const ServiceManager = lazyImport(
  () => import("./components/service/ServiceManager")
);
const SalesManager = lazyImport(() => import("./components/sales/SalesManager"));
const WarrantyManager = lazyImport(
  () => import("./components/warranty/WarrantyManager").then((m) => ({
    default: m.WarrantyManager,
  }))
);
const ServiceHistory = lazyImport(() =>
  import("./components/service/ServiceHistory").then((m) => ({
    default: m.ServiceHistory,
  }))
);
const CustomerManager = lazyImport(
  () => import("./components/customer/CustomerManager")
);

const CategoriesManager = lazyImport(
  () => import("./components/categories/CategoriesManager")
);
const LookupManager = lazyImport(() => import("./components/lookup/LookupManager"));
const MigrationTool = lazyImport(() => import("./components/admin/MigrationTool"));
const ReportsOverview = lazyImport(() => import("./components/reports/ReportsOverview"));
const CashBookPage = lazyImport(() => import("./components/finance/CashBookPage"));
const SettingsManager = lazyImport(() =>
  import("./components/settings/SettingsManager").then((m) => ({
    default: m.SettingsManager,
  }))
);
const EmployeesManager = lazyImport(
  () => import("./components/employees/EmployeesManager")
);
const StaffDashboard = lazyImport(() =>
  import("./components/dashboard/StaffDashboard").then((m) => ({
    default: m.StaffDashboard,
  }))
);

// Loading component for Suspense fallback
const PageLoader = () => (
  <div className="flex items-center justify-center min-h-[50vh]">
    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
  </div>
);

// Finance, Sales, Reports components removed

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 2 * 60 * 1000,
      gcTime: 5 * 60 * 1000,
      refetchOnWindowFocus: false,
      refetchOnReconnect: "always",
      retry: 2,
    },
  },
});

// Attach global error handlers using built-in callbacks by extending QueryCache/MutationCache
// Simplified: we rely on per-query onError via a wrapper helper if needed; fallback here is noop.

if (import.meta.env.DEV && typeof window !== "undefined") {
  window.localStorage.removeItem("TanstackQueryDevtools.pip_open");
}

// MainLayout components
const Inventory = () => (
  <Suspense fallback={<PageLoader />}>
    <InventoryManager />
  </Suspense>
);
const Service = () => (
  <Suspense fallback={<PageLoader />}>
    <ServiceManager />
  </Suspense>
);
const Sales = () => (
  <Suspense fallback={<PageLoader />}>
    <SalesManager />
  </Suspense>
);
const ServiceHistoryPage = () => {
  const { currentBranchId } = useAppContext();
  return (
    <Suspense fallback={<PageLoader />}>
      <ServiceHistory currentBranchId={currentBranchId} />
    </Suspense>
  );
};
const Customers = () => (
  <Suspense fallback={<PageLoader />}>
    <CustomerManager />
  </Suspense>
);
const CategoriesPage = () => (
  <Suspense fallback={<PageLoader />}>
    <CategoriesManager />
  </Suspense>
);
const LookupPage = () => (
  <Suspense fallback={<PageLoader />}>
    <LookupManager />
  </Suspense>
);
const SettingsPage = () => (
  <Suspense fallback={<PageLoader />}>
    <SettingsManager />
  </Suspense>
);
const StaffDashboardPage = () => (
  <Suspense fallback={<PageLoader />}>
    <StaffDashboard />
  </Suspense>
);
const ReportsPage = () => (
  <Suspense fallback={<PageLoader />}>
    <ReportsOverview />
  </Suspense>
);
const CashBook = () => (
  <Suspense fallback={<PageLoader />}>
    <CashBookPage />
  </Suspense>
);
const EmployeesPage = () => (
  <Suspense fallback={<PageLoader />}>
    <EmployeesManager />
  </Suspense>
);
const MigrationPage = () => (
  <Suspense fallback={<PageLoader />}>
    <MigrationTool />
  </Suspense>
);
const WarrantyPage = () => (
  <Suspense fallback={<PageLoader />}>
    <WarrantyManager />
  </Suspense>
);


const MainLayout: React.FC = () => {
  const location = useLocation();
  const isShopPage = false; // Public shop pages removed
  const isWidePage = [
    "/service",
    "/sales",
    "/service-history",
    "/inventory",
    "/customers",
    "/employees",
    "/settings",
    "/warranty",
    "/categories",
    "/lookup",
    "/cash-book",
  ].some((path) => location.pathname.startsWith(path));

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors pb-20 md:pb-0 relative overflow-hidden">
      {!isShopPage && <Nav />}
      <main
        className={
          isWidePage
            ? "w-full px-0 md:px-4 lg:px-5"
            : "max-w-[1600px] mx-auto p-0 md:p-6"
        }
      >
        <Routes>
          <Route path="/" element={<RoleBasedRedirect />} />
          <Route
            path="/dashboard"
            element={
              <ProtectedRoute requiredRoles={["owner", "manager"]}>
                <Dashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/reports"
            element={
              <ProtectedRoute
                allow={({ profile }) => canDo(profile, "reports.view")}
                denyMessage="Bạn không có quyền xem báo cáo."
              >
                <ReportsPage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/cash-book"
            element={
              <ProtectedRoute
                allow={({ profile }) =>
                  canDo(profile, "cashbook.view") || canDo(profile, "finance.view")
                }
                denyMessage="Bạn không có quyền xem sổ quỹ."
              >
                <CashBook />
              </ProtectedRoute>
            }
          />
          <Route
            path="/staff-dashboard"
            element={
              <ProtectedRoute requiredRoles={["staff"]}>
                <StaffDashboardPage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/sales"
            element={
              <ProtectedRoute
                allow={({ profile }) => canDo(profile, "sale.create")}
                denyMessage="Bạn không có quyền sử dụng chức năng bán hàng."
              >
                <Sales />
              </ProtectedRoute>
            }
          />
          <Route
            path="/inventory"
            element={
              <ProtectedRoute
                allow={({ profile, user }) =>
                  canAccessInventorySection(profile, user)
                }
                denyMessage="Chỉ quản lý kho, nhân viên bán hàng, quản lý hoặc chủ cửa hàng mới được vào Kho."
              >
                <Inventory />
              </ProtectedRoute>
            }
          />
          <Route path="/categories" element={<CategoriesPage />} />
          <Route path="/lookup" element={<LookupPage />} />
          <Route path="/service" element={<Service />} />
          <Route
            path="/service-history"
            element={
              <ProtectedRoute
                allow={({ profile }) => canDo(profile, "work_order.history.view")}
                denyMessage="Bạn không có quyền xem lịch sử sửa chữa."
              >
                <ServiceHistoryPage />
              </ProtectedRoute>
            }
          />
          <Route path="/warranty" element={<WarrantyPage />} />
          <Route path="/customers" element={<Customers />} />
          <Route
            path="/employees"
            element={
              <ProtectedRoute requiredRoles={["owner", "manager"]}>
                <EmployeesPage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/settings"
            element={
              <ProtectedRoute requiredRoles={["owner", "manager"]}>
                <SettingsPage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/admin/migration"
            element={
              <ProtectedRoute requiredRoles={["owner"]}>
                <Suspense fallback={<PageLoader />}>
                  <MigrationTool />
                </Suspense>
              </ProtectedRoute>
            }
          />
        </Routes>
      </main>
      {/* Bottom Navigation for Mobile */}
      {!isShopPage && <BottomNav />}
    </div>
  );
};

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <AuthProvider>
          <AppProvider>
            <BrowserRouter>
              <ErrorBoundary>
                <TopProgressBar />
                <Routes>
                  {/* Public Routes - No authentication */}
                  <Route path="/login" element={<LoginPage />} />
                  <Route
                    path="/reset-password"
                    element={<ResetPasswordPage />}
                  />

                  {/* Public Shop Pages - No authentication required */}
                  {/* Public Shop Pages removed */}

                  {/* Protected Routes - Require authentication */}
                  <Route
                    path="/*"
                    element={
                      <ProtectedRoute>
                        <MainLayout />
                      </ProtectedRoute>
                    }
                  />
                </Routes>
                {import.meta.env.DEV && <ReactQueryDevtools initialIsOpen={false} />}
                {/* Dev-only repository error panel */}
                {import.meta.env.DEV && <RepoErrorPanel />}
              </ErrorBoundary>
            </BrowserRouter>
          </AppProvider>
        </AuthProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

import React, { useState } from "react";
import { supabase } from "../../supabaseClient";

interface MigrationResults {
  customers: { success: number; failed: number; skipped: number };
  parts: { success: number; failed: number; skipped: number };
  sales: { success: number; failed: number; skipped: number };
  paymentSources: { success: number; failed: number; skipped: number };
  suppliers: { success: number; failed: number; skipped: number };
  inventoryTransactions: { success: number; failed: number; skipped: number };
}

interface SupabaseCounts {
  customers: number;
  parts: number;
  sales: number;
  paymentSources: number;
  suppliers: number;
  inventoryTransactions: number;
  cashTransactions: number;
  workOrders: number;
}

export const MigrationTool: React.FC = () => {
  const [isRunning, setIsRunning] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [results, setResults] = useState<MigrationResults | null>(null);
  const [localData, setLocalData] = useState<any>(null);
  const [supabaseCounts, setSupabaseCounts] = useState<SupabaseCounts | null>(
    null
  );

  const addLog = (msg: string) => {
    setLogs((prev) => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);
  };

  const loadLocalData = () => {
    const stored = localStorage.getItem("motocare-data");
    if (!stored) {
      addLog("❌ Không tìm thấy dữ liệu trong localStorage");
      return null;
    }
    try {
      const data = JSON.parse(stored);
      setLocalData(data);
      addLog(`📦 Tìm thấy dữ liệu localStorage:`);
      addLog(`   - Parts: ${data.parts?.length || 0}`);
      addLog(`   - Customers: ${data.customers?.length || 0}`);
      addLog(`   - Sales: ${data.sales?.length || 0}`);
      addLog(`   - Suppliers: ${data.suppliers?.length || 0}`);
      addLog(`   - PaymentSources: ${data.paymentSources?.length || 0}`);
      addLog(
        `   - InventoryTransactions: ${data.inventoryTransactions?.length || 0}`
      );
      return data;
    } catch (e) {
      addLog("❌ Lỗi parse dữ liệu localStorage");
      return null;
    }
  };

  const runMigration = async () => {
    setIsRunning(true);
    setLogs([]);
    setResults(null);

    const data = loadLocalData();
    if (!data) {
      setIsRunning(false);
      return;
    }

    const res: MigrationResults = {
      customers: { success: 0, failed: 0, skipped: 0 },
      parts: { success: 0, failed: 0, skipped: 0 },
      sales: { success: 0, failed: 0, skipped: 0 },
      paymentSources: { success: 0, failed: 0, skipped: 0 },
      suppliers: { success: 0, failed: 0, skipped: 0 },
      inventoryTransactions: { success: 0, failed: 0, skipped: 0 },
    };

    // 1. CUSTOMERS
    addLog("\n📋 1. Di chuyển KHÁCH HÀNG...");
    if (data.customers?.length > 0) {
      for (const customer of data.customers) {
        try {
          const { data: existing } = await supabase
            .from("customers")
            .select("id")
            .eq("id", customer.id)
            .maybeSingle();

          if (existing) {
            res.customers.skipped++;
            continue;
          }

          const payload = {
            id: customer.id,
            name: customer.name,
            phone: customer.phone || null,
            created_at: customer.created_at || new Date().toISOString(),
          };

          const { error } = await supabase.from("customers").insert([payload]);
          if (error) {
            addLog(`  ❌ Customer ${customer.name}: ${error.message}`);
            res.customers.failed++;
          } else {
            res.customers.success++;
          }
        } catch (e: any) {
          res.customers.failed++;
        }
      }
      addLog(
        `  ✅ Customers: ${res.customers.success} OK, ${res.customers.skipped} skip, ${res.customers.failed} fail`
      );
    }

    // 2. SUPPLIERS
    addLog("\n📋 2. Di chuyển NHÀ CUNG CẤP...");
    if (data.suppliers?.length > 0) {
      for (const supplier of data.suppliers) {
        try {
          const { data: existing } = await supabase
            .from("suppliers")
            .select("id")
            .eq("id", supplier.id)
            .maybeSingle();

          if (existing) {
            res.suppliers.skipped++;
            continue;
          }

          const payload = {
            id: supplier.id,
            name: supplier.name,
            phone: supplier.phone || null,
            email: supplier.email || null,
            address: supplier.address || null,
            created_at: supplier.created_at || new Date().toISOString(),
          };

          const { error } = await supabase.from("suppliers").insert([payload]);
          if (error) {
            addLog(`  ❌ Supplier ${supplier.name}: ${error.message}`);
            res.suppliers.failed++;
          } else {
            res.suppliers.success++;
          }
        } catch (e: any) {
          res.suppliers.failed++;
        }
      }
      addLog(
        `  ✅ Suppliers: ${res.suppliers.success} OK, ${res.suppliers.skipped} skip, ${res.suppliers.failed} fail`
      );
    }

    // 3. PAYMENT SOURCES
    addLog("\n📋 3. Di chuyển NGUỒN TIỀN...");
    if (data.paymentSources?.length > 0) {
      for (const ps of data.paymentSources) {
        try {
          const { data: existing } = await supabase
            .from("payment_sources")
            .select("id")
            .eq("id", ps.id)
            .maybeSingle();

          if (existing) {
            res.paymentSources.skipped++;
            continue;
          }

          const payload = {
            id: ps.id,
            name: ps.name,
            balance: ps.balance || {},
            created_at: new Date().toISOString(),
          };

          const { error } = await supabase
            .from("payment_sources")
            .insert([payload]);
          if (error) {
            addLog(`  ❌ PaymentSource ${ps.name}: ${error.message}`);
            res.paymentSources.failed++;
          } else {
            res.paymentSources.success++;
          }
        } catch (e: any) {
          res.paymentSources.failed++;
        }
      }
      addLog(
        `  ✅ PaymentSources: ${res.paymentSources.success} OK, ${res.paymentSources.skipped} skip, ${res.paymentSources.failed} fail`
      );
    }

    // 4. PARTS
    addLog("\n📋 4. Di chuyển PHỤ TÙNG...");
    if (data.parts?.length > 0) {
      for (const part of data.parts) {
        try {
          const { data: existing } = await supabase
            .from("parts")
            .select("id")
            .eq("id", part.id)
            .maybeSingle();

          if (existing) {
            res.parts.skipped++;
            continue;
          }

          // Also check by SKU
          const { data: existingSku } = await supabase
            .from("parts")
            .select("id")
            .eq("sku", part.sku)
            .maybeSingle();

          if (existingSku) {
            res.parts.skipped++;
            continue;
          }

          const payload = {
            id: part.id,
            name: part.name,
            sku: part.sku,
            stock: part.stock || {},
            retailprice: part.retailPrice || {},
            wholesaleprice: part.wholesalePrice || {},
            category: part.category || null,
            description: part.description || null,
            warrantyperiod: part.warrantyPeriod || null,
            costprice: part.costPrice || {},
            created_at: part.created_at || new Date().toISOString(),
          };

          const { error } = await supabase.from("parts").insert([payload]);
          if (error) {
            addLog(`  ❌ Part ${part.name} (${part.sku}): ${error.message}`);
            res.parts.failed++;
          } else {
            res.parts.success++;
          }
        } catch (e: any) {
          res.parts.failed++;
        }
      }
      addLog(
        `  ✅ Parts: ${res.parts.success} OK, ${res.parts.skipped} skip, ${res.parts.failed} fail`
      );
    }

    // 5. SALES
    addLog("\n📋 5. Di chuyển ĐƠN BÁN HÀNG...");
    if (data.sales?.length > 0) {
      for (const sale of data.sales) {
        try {
          const { data: existing } = await supabase
            .from("sales")
            .select("id")
            .eq("id", sale.id)
            .maybeSingle();

          if (existing) {
            res.sales.skipped++;
            continue;
          }

          const payload = {
            id: sale.id,
            date: sale.date || new Date().toISOString(),
            items: sale.items || [],
            subtotal: sale.subtotal || 0,
            discount: sale.discount || 0,
            total: sale.total || 0,
            customer: sale.customer || { name: "Khách lẻ" },
            paymentmethod: sale.paymentMethod || "cash",
            userid: sale.userId || "migrated",
            username: sale.userName || "Migrated User",
            branchid: sale.branchId || "CN1",
            cashtransactionid: sale.cashTransactionId || null,
            created_at:
              sale.created_at || sale.date || new Date().toISOString(),
          };

          const { error } = await supabase.from("sales").insert([payload]);
          if (error) {
            addLog(`  ❌ Sale ${sale.id}: ${error.message}`);
            res.sales.failed++;
          } else {
            res.sales.success++;
          }
        } catch (e: any) {
          res.sales.failed++;
        }
      }
      addLog(
        `  ✅ Sales: ${res.sales.success} OK, ${res.sales.skipped} skip, ${res.sales.failed} fail`
      );
    }

    // 6. INVENTORY TRANSACTIONS
    addLog("\n📋 6. Di chuyển GIAO DỊCH KHO...");
    if (data.inventoryTransactions?.length > 0) {
      for (const tx of data.inventoryTransactions) {
        try {
          const { data: existing } = await supabase
            .from("inventory_transactions")
            .select("id")
            .eq("id", tx.id)
            .maybeSingle();

          if (existing) {
            res.inventoryTransactions.skipped++;
            continue;
          }

          const payload = {
            id: tx.id,
            type: tx.type,
            partid: tx.partId,
            partname: tx.partName,
            quantity: tx.quantity || 0,
            date: tx.date || new Date().toISOString(),
            unitprice: tx.unitPrice || 0,
            totalprice: tx.totalPrice || 0,
            branchid: tx.branchId || "CN1",
            notes: tx.notes || null,
            saleid: tx.saleId || null,
            workorderid: tx.workOrderId || null,
            supplierid: tx.supplierId || null,
            created_at: tx.created_at || tx.date || new Date().toISOString(),
          };

          const { error } = await supabase
            .from("inventory_transactions")
            .insert([payload]);
          if (error) {
            addLog(`  ❌ InventoryTx ${tx.id}: ${error.message}`);
            res.inventoryTransactions.failed++;
          } else {
            res.inventoryTransactions.success++;
          }
        } catch (e: any) {
          res.inventoryTransactions.failed++;
        }
      }
      addLog(
        `  ✅ InventoryTx: ${res.inventoryTransactions.success} OK, ${res.inventoryTransactions.skipped} skip, ${res.inventoryTransactions.failed} fail`
      );
    }

    setResults(res);
    addLog("\n✅ HOÀN TẤT DI CHUYỂN!");
    addLog("💡 Refresh trang web để xem dữ liệu mới từ Supabase.");
    setIsRunning(false);

    // Auto check Supabase after migration
    await checkSupabaseData();
  };

  // Check Supabase data counts
  const checkSupabaseData = async () => {
    addLog("\n🔍 Kiểm tra dữ liệu trong Supabase...");
    try {
      const counts: SupabaseCounts = {
        customers: 0,
        parts: 0,
        sales: 0,
        paymentSources: 0,
        suppliers: 0,
        inventoryTransactions: 0,
        cashTransactions: 0,
        workOrders: 0,
      };

      const { count: custCount } = await supabase
        .from("customers")
        .select("*", { count: "exact", head: true });
      counts.customers = custCount || 0;

      const { count: partsCount } = await supabase
        .from("parts")
        .select("*", { count: "exact", head: true });
      counts.parts = partsCount || 0;

      const { count: salesCount } = await supabase
        .from("sales")
        .select("*", { count: "exact", head: true });
      counts.sales = salesCount || 0;

      const { count: psCount } = await supabase
        .from("payment_sources")
        .select("*", { count: "exact", head: true });
      counts.paymentSources = psCount || 0;

      const { count: suppCount } = await supabase
        .from("suppliers")
        .select("*", { count: "exact", head: true });
      counts.suppliers = suppCount || 0;

      const { count: invTxCount } = await supabase
        .from("inventory_transactions")
        .select("*", { count: "exact", head: true });
      counts.inventoryTransactions = invTxCount || 0;

      const { count: cashTxCount } = await supabase
        .from("cash_transactions")
        .select("*", { count: "exact", head: true });
      counts.cashTransactions = cashTxCount || 0;

      const { count: woCount } = await supabase
        .from("work_orders")
        .select("*", { count: "exact", head: true });
      counts.workOrders = woCount || 0;

      setSupabaseCounts(counts);

      addLog(`\n📊 DỮ LIỆU TRONG SUPABASE:`);
      addLog(`   - Customers: ${counts.customers}`);
      addLog(`   - Parts: ${counts.parts}`);
      addLog(`   - Sales: ${counts.sales}`);
      addLog(`   - Payment Sources: ${counts.paymentSources}`);
      addLog(`   - Suppliers: ${counts.suppliers}`);
      addLog(`   - Inventory Transactions: ${counts.inventoryTransactions}`);
      addLog(`   - Cash Transactions: ${counts.cashTransactions}`);
      addLog(`   - Work Orders: ${counts.workOrders}`);

      // Show recent sales
      if (counts.sales > 0) {
        const { data: recentSales } = await supabase
          .from("sales")
          .select("id, date, total, branchid")
          .order("date", { ascending: false })
          .limit(3);

        if (recentSales?.length) {
          addLog(`\n📋 3 đơn bán hàng gần nhất:`);
          recentSales.forEach((s, i) => {
            addLog(
              `   ${i + 1}. ${s.date?.slice(
                0,
                10
              )} - ${s.total?.toLocaleString()}đ (${s.branchid})`
            );
          });
        }
      }
    } catch (e: any) {
      addLog(`❌ Lỗi kiểm tra Supabase: ${e.message}`);
    }
  };

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">
        🔄 Di chuyển dữ liệu localStorage → Supabase
      </h1>

      <div className="mb-4 p-4 bg-yellow-50 border border-yellow-200 rounded">
        <p className="text-yellow-800">
          ⚠️ <strong>Lưu ý:</strong> Script này sẽ di chuyển dữ liệu từ
          localStorage sang Supabase. Các bản ghi đã tồn tại sẽ được bỏ qua
          (không ghi đè).
        </p>
      </div>

      <div className="flex flex-wrap gap-4 mb-4">
        <button
          onClick={loadLocalData}
          disabled={isRunning}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 disabled:opacity-50"
        >
          📦 Xem dữ liệu localStorage
        </button>
        <button
          onClick={checkSupabaseData}
          disabled={isRunning}
          className="px-4 py-2 bg-purple-500 text-white rounded hover:bg-purple-600 disabled:opacity-50"
        >
          🔍 Kiểm tra Supabase
        </button>
        <button
          onClick={runMigration}
          disabled={isRunning}
          className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600 disabled:opacity-50"
        >
          {isRunning ? "⏳ Đang di chuyển..." : "🚀 Bắt đầu di chuyển"}
        </button>
      </div>

      {supabaseCounts && (
        <div className="mb-4 p-4 bg-purple-50 border border-purple-200 rounded">
          <h3 className="font-bold mb-2">🗄️ Dữ liệu trong Supabase:</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-sm">
            <div>
              Customers: <strong>{supabaseCounts.customers}</strong>
            </div>
            <div>
              Parts: <strong>{supabaseCounts.parts}</strong>
            </div>
            <div>
              Sales: <strong>{supabaseCounts.sales}</strong>
            </div>
            <div>
              Work Orders: <strong>{supabaseCounts.workOrders}</strong>
            </div>
            <div>
              Cash Transactions:{" "}
              <strong>{supabaseCounts.cashTransactions}</strong>
            </div>
            <div>
              Payment Sources: <strong>{supabaseCounts.paymentSources}</strong>
            </div>
            <div>
              Suppliers: <strong>{supabaseCounts.suppliers}</strong>
            </div>
            <div>
              Inventory Tx:{" "}
              <strong>{supabaseCounts.inventoryTransactions}</strong>
            </div>
          </div>
        </div>
      )}

      {results && (
        <div className="mb-4 p-4 bg-green-50 border border-green-200 rounded">
          <h3 className="font-bold mb-2">📊 Kết quả Migration:</h3>
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b">
                <th className="text-left py-1">Bảng</th>
                <th className="text-center py-1">✅ Thành công</th>
                <th className="text-center py-1">⏭️ Bỏ qua</th>
                <th className="text-center py-1">❌ Lỗi</th>
