              "Bật 2FA ngay"
            )}
          </button>
        )}
      </div>
    );
  }

  // Verify enrollment step
  if (step === "verify") {
    return (
      <div className="space-y-5">
        {/* QR Code */}
        <div className="text-center">
          <p className="text-sm text-slate-600 dark:text-slate-400 mb-3">
