import React, { useState, useRef, useEffect, useCallback } from 'react';
import { RefreshCcw } from 'lucide-react';

interface AndroidPatternLockProps {
    onPatternComplete?: (pattern: string) => void;
    className?: string;
    initialValue?: string; // Format "1-2-3-4"
    readOnly?: boolean;
}

export const AndroidPatternLock: React.FC<AndroidPatternLockProps> = ({
    onPatternComplete,
    className = '',
    initialValue = '',
    readOnly = false
}) => {
    // Initialize state from initialValue if present
    const [pattern, setPattern] = useState<number[]>(() => {
        if (!initialValue) return [];
        return initialValue.split('-').map(Number).filter(n => !isNaN(n));
    });

    // Update pattern when initialValue changes matches
    useEffect(() => {
        if (initialValue) {
            setPattern(initialValue.split('-').map(Number).filter(n => !isNaN(n)));
        }
    }, [initialValue]);

    const [isDragging, setIsDragging] = useState(false);
    const svgRef = useRef<SVGSVGElement>(null);

    // Grid configuration
    const DOT_RADIUS = 6;
    const ACTIVE_DOT_RADIUS = 12; // Larger halo
    const HIT_RADIUS = 25; // Hit area
    const GRID_SIZE = 3;
    const GAP = 80;
    const OFFSET = 40;

    // 1-9 coordinates
    const dots = Array.from({ length: 9 }, (_, i) => ({
        id: i + 1,
        x: (i % GRID_SIZE) * GAP + OFFSET,
        y: Math.floor(i / GRID_SIZE) * GAP + OFFSET
    }));

    const getTouchedDot = (clientX: number, clientY: number) => {
        if (!svgRef.current) return null;
        const rect = svgRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        return dots.find(dot => {
            const distance = Math.sqrt(Math.pow(dot.x - x, 2) + Math.pow(dot.y - y, 2));
            return distance < HIT_RADIUS;
        });
    };

    const handleStart = (e: React.MouseEvent | React.TouchEvent) => {
        if (readOnly) return; // Disable interaction if readOnly
        e.preventDefault(); // Prevent scrolling on touch
        setIsDragging(true);
        setPattern([]);

        // Check initial touch
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

        const dot = getTouchedDot(clientX, clientY);
        if (dot) {
            setPattern([dot.id]);
        }
    };

    const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
        if (!isDragging || readOnly) return;
        e.preventDefault();

        const clientX = 'touches' in e ? (e as TouchEvent).touches[0].clientX : (e as MouseEvent).clientX;
        const clientY = 'touches' in e ? (e as TouchEvent).touches[0].clientY : (e as MouseEvent).clientY;

        const dot = getTouchedDot(clientX, clientY);
        if (dot && !pattern.includes(dot.id)) {
            // Optional: Check for skipping dots (e.g. 1->3 should capture 2).
            // For simplicity, we assume direct connection or implement midpoint logic later if needed.
            // Implementing simple midway point check:
            const lastDotId = pattern[pattern.length - 1];
            if (lastDotId) {
                const lastDot = dots.find(d => d.id === lastDotId)!;
                // Check if midpoint is skipped
                const midX = (lastDot.x + dot.x) / 2;
                const midY = (lastDot.y + dot.y) / 2;
                const midDot = dots.find(d => Math.abs(d.x - midX) < 5 && Math.abs(d.y - midY) < 5);
                if (midDot && !pattern.includes(midDot.id)) {
                    setPattern(prev => [...prev, midDot.id, dot.id]);
                    return;
                }
            }
            setPattern(prev => [...prev, dot.id]);
        }
    }, [isDragging, pattern, readOnly]);

    const handleEnd = useCallback(() => {
        if (isDragging) {
            setIsDragging(false);
            if (pattern.length > 0 && onPatternComplete) {
                onPatternComplete(pattern.join('-'));
            }
        }
    }, [isDragging, pattern, onPatternComplete]);

    // Global event listeners for drag outside the SVG
    useEffect(() => {
        if (isDragging) {
            window.addEventListener('mousemove', handleMove);
            window.addEventListener('mouseup', handleEnd);
            window.addEventListener('touchmove', handleMove, { passive: false });
            window.addEventListener('touchend', handleEnd);
        }
        return () => {
            window.removeEventListener('mousemove', handleMove);
            window.removeEventListener('mouseup', handleEnd);
            window.removeEventListener('touchmove', handleMove);
            window.removeEventListener('touchend', handleEnd);
        };
    }, [isDragging, handleMove, handleEnd]);

    const containerSize = GAP * 2 + OFFSET * 2;
    // Scale down if readOnly to make it smaller
    const scale = readOnly ? 0.6 : 1;
    const size = containerSize * scale;

    return (
        <div className={`flex flex-col items-center ${className}`}>
            <div className="relative mb-2 select-none touch-none"
                style={{
                    width: size,
                    height: size,
                }}
                onMouseDown={handleStart}
                onTouchStart={handleStart}
            >
                <div style={{ transform: `scale(${scale})`, transformOrigin: 'top left' }}>
                    <svg
                        ref={svgRef}
                        width={containerSize}
                        height={containerSize}
                        className={`rounded-3xl shadow-inner block ${readOnly ? 'bg-transparent border border-slate-200 dark:border-slate-700' : 'bg-slate-100 dark:bg-slate-800 cursor-pointer'}`}
                        style={{ touchAction: 'none' }}
                    >
                        {/* Connection Lines */}
                        <polyline
                            points={pattern.map(id => {
                                const d = dots.find(d => d.id === id);
                                return `${d?.x},${d?.y}`;
                            }).join(' ')}
                            fill="none"
                            stroke={readOnly ? "#10b981" : "#3b82f6"} // Emerald for readonly (view), Blue for edit
                            strokeWidth="3"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            className="opacity-80"
                        />

                        {/* Dots */}
                        {dots.map(dot => {
                            const isActive = pattern.includes(dot.id);
                            return (
                                <g key={dot.id}>
                                    {/* Hit area (invisible) */}
                                    <circle cx={dot.x} cy={dot.y} r={HIT_RADIUS} fill="transparent" />
                                    {/* Outer Glow for active */}
                                    {!readOnly && (
                                        <circle
                                            cx={dot.x}
                                            cy={dot.y}
                                            r={isActive ? ACTIVE_DOT_RADIUS : 0}
                                            fill="rgba(59, 130, 246, 0.2)"
                                            className="transition-all duration-300"
                                        />
                                    )}
                                    {/* Core Dot */}
                                    <circle
                                        cx={dot.x}
                                        cy={dot.y}
                                        r={DOT_RADIUS}
                                        fill={isActive ? (readOnly ? "#10b981" : "#3b82f6") : "#94a3b8"}
                                        className="transition-colors duration-200"
                                    />
                                </g>
                            );
                        })}
                    </svg>
                </div>
            </div>

            {!readOnly && pattern.length > 0 && (
                <button
                    onClick={() => { setPattern([]); if (onPatternComplete) onPatternComplete(""); }}
                    className="text-xs flex items-center gap-1 text-slate-500 hover:text-red-500 transition-colors mt-2"
                >
                    <RefreshCcw className="w-3 h-3" /> Vẽ lại
                </button>
            )}
        </div>
    );
};

import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode, Html5QrcodeResult } from "html5-qrcode";
import { X } from "lucide-react";

interface BarcodeScannerProps {
  onResult: (result: string) => void;
  onClose: () => void;
  isScanning: boolean;
}

export const BarcodeScanner: React.FC<BarcodeScannerProps> = ({
  onResult,
  onClose,
  isScanning,
}) => {
  const scannerRef = useRef<Html5Qrcode | null>(null);
  const [error, setError] = useState<string>("");

  useEffect(() => {
    if (isScanning && !scannerRef.current) {
      const config = {
        fps: 10,
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0,
      };

      const html5QrCode = new Html5Qrcode("reader");
      scannerRef.current = html5QrCode;

      html5QrCode
        .start(
          { facingMode: "environment" },
          config,
          (decodedText, _decodedResult) => {
            onResult(decodedText);
            // Stop scanning after successful read? Usually yes for this use case
            // But let parent handle closing
          },
          (errorMessage) => {
            // scan failure, usually ignore
            // console.warn(errorMessage);
          }
        )
        .catch((err) => {
          console.error("Error starting scanner", err);
          setError("Không thể khởi động camera. Vui lòng cấp quyền.");
        });
    }

    return () => {
      if (scannerRef.current && scannerRef.current.isScanning) {
        scannerRef.current
          .stop()
          .then(() => {
            scannerRef.current?.clear();
            scannerRef.current = null;
          })
          .catch((err) => console.error("Failed to stop scanner", err));
      }
    };
  }, [isScanning, onResult]);

  if (!isScanning) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col">
      <div className="flex justify-between items-center p-4 bg-black/50 absolute top-0 left-0 right-0 z-10">
        <h3 className="text-white font-bold">Quét mã vạch</h3>
        <button onClick={onClose} className="p-2 bg-white/20 rounded-full text-white">
          <X size={24} />
        </button>
      </div>

      <div id="reader" className="w-full h-full bg-black"></div>

      {error && (
        <div className="absolute bottom-10 left-0 right-0 p-4 text-center text-red-500 bg-black/80">
          {error}
        </div>
      )}
      <div className="absolute bottom-20 left-0 right-0 text-center text-white/70 text-sm">
        Đưa mã vạch vào khung hình
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from "react";
import { X, Camera, FlashlightOff, Flashlight, SwitchCamera } from "lucide-react";
import { Html5Qrcode, Html5QrcodeScannerState } from "html5-qrcode";

interface BarcodeScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onScan: (barcode: string) => void;
  title?: string;
}

const BarcodeScannerModal: React.FC<BarcodeScannerModalProps> = ({
  isOpen,
  onClose,
  onScan,
  title = "Quét mã vạch",
}) => {
  const scannerRef = useRef<Html5Qrcode | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [torchOn, setTorchOn] = useState(false);
  const [facingMode, setFacingMode] = useState<"environment" | "user">("environment");
  const [lastScanned, setLastScanned] = useState<string>("");
  const hasScannedRef = useRef(false);
  const mountedRef = useRef(true);

  // Dừng scanner và gọi callback
  const handleSuccessfulScan = useCallback(async (decodedText: string) => {
    // Chỉ xử lý 1 lần
    if (hasScannedRef.current) return;
    hasScannedRef.current = true;


    // Vibrate
    if (navigator.vibrate) {
      navigator.vibrate(100);
    }

    setLastScanned(decodedText);

    // Dừng scanner trước
    if (scannerRef.current) {
      try {
        const state = scannerRef.current.getState();
        if (state === Html5QrcodeScannerState.SCANNING) {
          await scannerRef.current.stop();
        }
      } catch (e) {
        // Ignore
      }
    }
    setIsScanning(false);

    // Delay nhỏ để UI cập nhật, rồi gọi callback và đóng
    setTimeout(() => {
      if (mountedRef.current) {
        onScan(decodedText);
        onClose();
      }
    }, 300);
  }, [onScan, onClose]);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    if (isOpen) {
      hasScannedRef.current = false;
      setLastScanned("");
      startScanner();
    } else {
      stopScanner();
    }

    return () => {
      stopScanner();
    };
  }, [isOpen, facingMode]);

  const startScanner = async () => {
    try {
      setError(null);

      // Stop existing scanner if any
      if (scannerRef.current) {
        try {
          const state = scannerRef.current.getState();
          if (state === Html5QrcodeScannerState.SCANNING) {
            await scannerRef.current.stop();
          }
          scannerRef.current.clear();
        } catch (e) {
          // Ignore
        }
      }

      const scanner = new Html5Qrcode("barcode-scanner-container");
      scannerRef.current = scanner;

      // iOS-optimized config with specific formats to improve performance
      const config: any = {
        fps: 20,
        qrbox: { width: 300, height: 180 },
        aspectRatio: 1.5,
        disableFlip: false,
        experimentalFeatures: {
          useBarCodeDetectorIfSupported: true,
        },
        // Limit formats to speed up detection on iOS JS-scanner
        formatsToSupport: [
          0, // QR_CODE
          3, // CODE_39
          5, // CODE_128 (Common for logistic/parts)
          9, // EAN_13 (Common products)
          10, // EAN_8
          14, // UPC_A
          15, // UPC_E
          2, // CODABAR
        ],
        videoConstraints: {
          facingMode: facingMode,
          focusMode: "continuous",
          width: { ideal: 1280 }, // 720p is good balance
          height: { ideal: 720 },
        },
      };

      await scanner.start(
        { facingMode },
        config,
        handleSuccessfulScan,
        () => {
          // Ignore scan errors (no code found)
        }
      );

      // Note: Do NOT apply zoom on iOS - it triggers macro mode and causes blur
      setIsScanning(true);
    } catch (err: any) {
      console.error("Scanner error:", err);
      if (err.toString().includes("NotAllowedError")) {
        setError("Vui lòng cấp quyền camera để quét mã vạch");
      } else if (err.toString().includes("NotFoundError")) {
        setError("Không tìm thấy camera trên thiết bị");
      } else {
        setError("Không thể khởi động camera: " + (err.message || err));
      }
      setIsScanning(false);
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current) {
      try {
        const state = scannerRef.current.getState();
        if (state === Html5QrcodeScannerState.SCANNING) {
          await scannerRef.current.stop();
        }
        scannerRef.current.clear();
      } catch (e) {
        // Ignore cleanup errors
      }
      scannerRef.current = null;
    }
    setIsScanning(false);
  };

  const toggleTorch = async () => {
    try {
      const track = (scannerRef.current as any)?.getRunningTrackCameraCapabilities?.();
      if (track?.torchFeature?.isSupported()) {
        await track.torchFeature.apply(!torchOn);
        setTorchOn(!torchOn);
      }
    } catch (e) {
    }
  };

  const switchCamera = () => {
    setFacingMode(prev => prev === "environment" ? "user" : "environment");
  };

  const handleClose = () => {
    stopScanner();
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/90 flex flex-col z-[200]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 bg-black/50">
        <h2 className="text-white font-semibold flex items-center gap-2">
          <Camera className="w-5 h-5" />
          {title}
        </h2>
        <button
          onClick={handleClose}
          className="p-2 rounded-full bg-white/20 text-white hover:bg-white/30"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Scanner Area */}
      <div className="flex-1 flex flex-col items-center justify-center p-4">
        {error ? (
          <div className="text-center">
            <div className="text-red-400 mb-4 px-4">{error}</div>
            <button
              onClick={startScanner}
              className="px-6 py-3 bg-blue-600 text-white rounded-lg font-medium"
            >
              Thử lại
            </button>
          </div>
        ) : (
          <>
            {/* Scanner container */}
            <div className="relative w-full max-w-sm">
              <div
                id="barcode-scanner-container"
                className="w-full rounded-xl overflow-hidden bg-black"
                style={{ minHeight: 300 }}
              />

              {/* Scan frame overlay */}
              {isScanning && (
                <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                  <div className="w-[300px] h-[180px] relative">
                    {/* Corner markers */}
                    <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-green-400 rounded-tl" />
                    <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-green-400 rounded-tr" />
                    <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-green-400 rounded-bl" />
                    <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-green-400 rounded-br" />

                    {/* Scanning line animation */}
                    <div className="absolute inset-x-0 h-0.5 bg-green-400 animate-scan" />
                  </div>
                </div>
              )}
            </div>

            {/* Last scanned */}
            {lastScanned && (
              <div className="mt-4 px-4 py-2 bg-green-600/20 border border-green-500 rounded-lg">
                <p className="text-green-400 text-sm text-center font-mono">
                  ✓ Đã quét: {lastScanned}
                </p>
              </div>
            )}

            {/* Instructions - with iOS distance guidance */}
            <div className="mt-4 text-center px-4">
              <p className="text-white/70 text-sm">
                Đưa mã vạch vào khung hình để quét
              </p>
              <p className="text-amber-400/80 text-xs mt-1">
                📱 iPhone: Giữ cách 15-25cm để tránh bị mờ
              </p>
            </div>
          </>
        )}
      </div>

      {/* Controls */}
      {isScanning && (
        <div className="flex items-center justify-center gap-6 p-6 bg-black/50">
          <button
            onClick={toggleTorch}
            className={`p-4 rounded-full ${torchOn ? "bg-yellow-500 text-black" : "bg-white/20 text-white"}`}
            title="Đèn flash"
          >
            {torchOn ? <Flashlight className="w-6 h-6" /> : <FlashlightOff className="w-6 h-6" />}
          </button>
          <button
            onClick={switchCamera}
            className="p-4 rounded-full bg-white/20 text-white"
            title="Đổi camera"
          >
            <SwitchCamera className="w-6 h-6" />
          </button>
        </div>
      )}

      {/* CSS for scan animation */}
      <style>{`
        @keyframes scan {
          0%, 100% { top: 0; }
          50% { top: calc(100% - 2px); }
        }
        .animate-scan {
          animation: scan 2s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

