import { useMemo } from "react";
// Sales repo removed
import { useWorkOrdersRepo } from "../../../hooks/useWorkOrdersRepository";
import { usePartsRepo } from "../../../hooks/usePartsRepository";
import { useCashTxRepo } from "../../../hooks/useCashTransactionsRepository";
// CashBalance and Loans repos removed
import { useAppContext } from "../../../contexts/AppContext";

import { calculateFinancialSummary } from "../../../lib/reports/financialSummary";

export const useDashboardData = (
    reportFilter: string,
    selectedMonth?: number,
    selectedQuarter?: number
) => {
    const sales: any[] = []; // Sales module removed
    const { data: workOrders = [] } = useWorkOrdersRepo();
    const { data: parts = [] } = usePartsRepo();
    const { data: cashTransactions = [] } = useCashTxRepo();
    // Stubs for removed hooks
    const { cashBalance, bankBalance } = { cashBalance: 0, bankBalance: 0 };
    const { data: loans = [] } = { data: [] as any[] };
    const { currentBranchId } = useAppContext();

    const today = new Date().toISOString().slice(0, 10);

    // Thống kê hôm nay (bao gồm cả Sales và Work Orders đã thanh toán)
    const todayStats = useMemo(() => {
        const start = new Date();
        start.setHours(0, 0, 0, 0);
        const end = new Date();
        end.setHours(23, 59, 59, 999);

        const summary = calculateFinancialSummary({
            sales,
            workOrders,
            parts,
            cashTransactions,
            branchId: currentBranchId,
            start,
            end,
        });

        const revenue = summary.combinedRevenue;
        const grossProfit = summary.totalProfit;
        const profit = summary.netProfit;
        const income = summary.cashIncome;
        const expense = summary.cashExpense;

        const salesCustomers = summary.filteredSales.map(
            (s: any) => s?.customer?.phone || s?.customer?.name
        );
        const woCustomers = summary.filteredWorkOrders.map(
            (wo: any) =>
                wo?.customerPhone ||
                wo?.customerphone ||
                wo?.customerName ||
                wo?.customername
        );
        const customerCount = new Set([...salesCustomers, ...woCustomers].filter(Boolean)).size;

        return {
            revenue,
            profit,
            grossProfit,
            income,
            expense,
            customerCount,
            orderCount: summary.orderCount,
            salesCount: summary.salesCount,
            workOrdersCount: summary.workOrdersCount,
        };
    }, [sales, workOrders, parts, cashTransactions, currentBranchId]);

    // Thống kê theo filter (bao gồm cả Sales và Work Orders)
    const filteredStats = useMemo(() => {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = now; // Ngày hiện tại

        // Handle specific month filters (month1, month2, ... month12)
        if (reportFilter.startsWith("month") && reportFilter.length > 5) {
            const monthNum = parseInt(reportFilter.slice(5), 10);
            if (monthNum >= 1 && monthNum <= 12) {
                startDate = new Date(now.getFullYear(), monthNum - 1, 1);
                endDate = new Date(now.getFullYear(), monthNum, 0); // Last day of month
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        }
        // Handle quarter filters (q1, q2, q3, q4)
        else if (reportFilter.startsWith("q") && reportFilter.length === 2) {
            const quarterNum = parseInt(reportFilter.slice(1), 10);
            if (quarterNum >= 1 && quarterNum <= 4) {
                const startMonth = (quarterNum - 1) * 3;
                startDate = new Date(now.getFullYear(), startMonth, 1);
                endDate = new Date(now.getFullYear(), startMonth + 3, 0); // Last day of quarter
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        }
        // Handle standard filters
        else {
            switch (reportFilter) {
                case "today":
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "7days":
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "week":
                    const dayOfWeek = now.getDay();
                    const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1; // Monday = 0
                    startDate = new Date(
                        now.getFullYear(),
                        now.getMonth(),
                        now.getDate() - diff
                    );
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "month":
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "year":
                    startDate = new Date(now.getFullYear(), 0, 1);
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                default:
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            }
        }

        // Sử dụng local date format YYYY-MM-DD thay vì ISO string (tránh lỗi timezone)
        const formatLocalDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        };

        // Chuyển ISO string hoặc date string sang local date string YYYY-MM-DD
        const toLocalDateStr = (
            dateStr: string | undefined | null
        ): string | null => {
            if (!dateStr) return null;
            try {
                // Parse date string và chuyển sang local date
                const d = new Date(dateStr);
                if (isNaN(d.getTime())) return null;
                return formatLocalDate(d);
            } catch {
                return null;
            }
        };

        startDate.setHours(0, 0, 0, 0);
        endDate.setHours(23, 59, 59, 999);

        const summary = calculateFinancialSummary({
            sales,
            workOrders,
            parts,
            cashTransactions,
            branchId: currentBranchId,
            start: startDate,
            end: endDate,
        });

        const revenue = summary.combinedRevenue;
        const grossProfit = summary.totalProfit;
        const profit = summary.netProfit;
        const income = summary.cashIncome;
        const expense = summary.cashExpense;

        const salesCustomers = summary.filteredSales.map(
            (s: any) => s?.customer?.phone || s?.customer?.name
        );
        const woCustomers = summary.filteredWorkOrders.map(
            (wo: any) =>
                wo?.customerPhone ||
                wo?.customerphone ||
                wo?.customerName ||
                wo?.customername
        );
        const customerCount = new Set([...salesCustomers, ...woCustomers].filter(Boolean)).size;

        return {
            revenue,
            profit,
            grossProfit,
            income,
            expense,
            customerCount,
            orderCount: summary.orderCount,
        };
    }, [sales, workOrders, parts, cashTransactions, reportFilter, currentBranchId]); // Added getPartCost to dependencyoanh thu 7 ngày gần nhất (bao gồm cả Sales và Work Orders)
    const last7DaysRevenue = useMemo(() => {
        const data = [];
        for (let i = 6; i >= 0; i--) {
            const date = new Date();
            date.setDate(date.getDate() - i);
            const dateStr = date.toISOString().slice(0, 10);

            // Sales revenue
            const daySales = sales.filter((s) => s.date.slice(0, 10) === dateStr);
            const salesRevenue = daySales.reduce((sum, s) => sum + s.total, 0);

            // Work Orders revenue (đã thanh toán)
            const dayWorkOrders = workOrders.filter((wo: any) => {
                const woDate =
                    wo.creationDate?.slice(0, 10) || wo.creationdate?.slice(0, 10);
                const isPaid =
                    wo.paymentStatus === "paid" ||
                    wo.paymentstatus === "paid" ||
                    wo.paymentStatus === "partial" ||
                    wo.paymentstatus === "partial";
                return woDate === dateStr && isPaid;
            });
            const woRevenue = dayWorkOrders.reduce(
                (sum, wo: any) => sum + (wo.totalPaid || wo.totalpaid || wo.total || 0),
                0
            );

            const revenue = salesRevenue + woRevenue;

            const expense = cashTransactions
                .filter((t) => t.type === "expense" && t.date.slice(0, 10) === dateStr)
                .reduce((sum, t) => sum + t.amount, 0);

            data.push({
                date: date.toLocaleDateString("vi-VN", {
                    day: "2-digit",
                    month: "2-digit",
                }),
                revenue,
                expense,
                profit: revenue - expense, // FIXME: This profit calc is simplified for the chart, ideally should be grossProfit - expense
            });
        }
        return data;
    }, [sales, workOrders, cashTransactions]);

    // Dữ liệu thu chi (lọc theo filter)
    const incomeExpenseData = useMemo(() => {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = now;

        // Tính toán date range theo filter (giống filteredStats)
        if (reportFilter.startsWith("month") && reportFilter.length > 5) {
            const monthNum = parseInt(reportFilter.slice(5), 10);
            if (monthNum >= 1 && monthNum <= 12) {
                startDate = new Date(now.getFullYear(), monthNum - 1, 1);
                endDate = new Date(now.getFullYear(), monthNum, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else if (reportFilter.startsWith("q") && reportFilter.length === 2) {
            const quarterNum = parseInt(reportFilter.slice(1), 10);
            if (quarterNum >= 1 && quarterNum <= 4) {
                const startMonth = (quarterNum - 1) * 3;
                startDate = new Date(now.getFullYear(), startMonth, 1);
                endDate = new Date(now.getFullYear(), startMonth + 3, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else {
            switch (reportFilter) {
                case "today":
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "7days":
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    break;
                case "week":
                    const dayOfWeek = now.getDay();
                    const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - diff);
                    break;
                case "month":
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
                    break;
                case "year":
                    startDate = new Date(now.getFullYear(), 0, 1);
                    break;
                default:
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        }

        const formatLocalDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        };
        const toLocalDateStr = (dateStr: string | undefined | null): string | null => {
            if (!dateStr) return null;
            try {
                const d = new Date(dateStr);
                if (isNaN(d.getTime())) return null;
                return formatLocalDate(d);
            } catch {
                return null;
            }
        };

        const startDateStr = formatLocalDate(startDate);
        const endDateStr = formatLocalDate(endDate);

        const income = cashTransactions
            .filter((t) => {
                const txDate = toLocalDateStr(t.date);
                return t.type === "income" && txDate && txDate >= startDateStr && txDate <= endDateStr;
            })
            .reduce((sum, t) => sum + t.amount, 0);
        const expense = cashTransactions
            .filter((t) => {
                const txDate = toLocalDateStr(t.date);
                return t.type === "expense" && txDate && txDate >= startDateStr && txDate <= endDateStr;
            })
            .reduce((sum, t) => sum + t.amount, 0);

        return [
            { name: "Thu", value: income, color: "#10b981" },
            { name: "Chi", value: expense, color: "#ef4444" },
        ];
    }, [cashTransactions, reportFilter]);

    // Top sản phẩm bán chạy (từ cả Sales và Work Orders - lọc theo filter)
    const topProducts = useMemo(() => {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = now;

        if (reportFilter.startsWith("month") && reportFilter.length > 5) {
            const monthNum = parseInt(reportFilter.slice(5), 10);
            if (monthNum >= 1 && monthNum <= 12) {
                startDate = new Date(now.getFullYear(), monthNum - 1, 1);
                endDate = new Date(now.getFullYear(), monthNum, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else if (reportFilter.startsWith("q") && reportFilter.length === 2) {
            const quarterNum = parseInt(reportFilter.slice(1), 10);
            if (quarterNum >= 1 && quarterNum <= 4) {
                const startMonth = (quarterNum - 1) * 3;
                startDate = new Date(now.getFullYear(), startMonth, 1);
                endDate = new Date(now.getFullYear(), startMonth + 3, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else {
            switch (reportFilter) {
                case "today":
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "7days":
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    break;
                case "week":
                    const dayOfWeek = now.getDay();
                    const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - diff);
                    break;
                case "month":
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
                    break;
                case "year":
                    startDate = new Date(now.getFullYear(), 0, 1);
                    break;
                default:
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        }

        const formatLocalDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        };
        const toLocalDateStr = (dateStr: string | undefined | null): string | null => {
            if (!dateStr) return null;
            try {
                const d = new Date(dateStr);
                if (isNaN(d.getTime())) return null;
                return formatLocalDate(d);
            } catch {
                return null;
            }
        };

        const startDateStr = formatLocalDate(startDate);
        const endDateStr = formatLocalDate(endDate);


        const productSales: Record<string, { name: string; quantity: number }> = {};

        // From sales (filtered)
        const filteredSales = sales.filter((s) => {
            const saleDate = toLocalDateStr(s.date);
            return saleDate && saleDate >= startDateStr && saleDate <= endDateStr;
        });

        filteredSales.forEach((sale) => {
            sale.items.forEach((item: any) => {
                // Ensure partId exists
                const pId = item.partId || (item as any).id;
                const pName = item.partName || "Sản phẩm không xác định";

                // DEBUG: Trace specific product
                if (pName.toLowerCase().includes("elf")) {
                }

                if (!pId) return;

                if (!productSales[pId]) {
                    productSales[pId] = {
                        name: pName,
                        quantity: 0,
                    };
                }
                productSales[pId].quantity += item.quantity || 0;
            });
        });


        // From work orders (filtered)
        const filteredWOs = workOrders.filter((wo: any) => {
            const woDate = toLocalDateStr(wo.creationDate || wo.creationdate);
            // EXCLUDE CANCELLED ORDERS
            const status = (wo.status || "").toLowerCase();
            const isCancelled = status === "đã hủy" || status === "cancelled";

            return woDate && woDate >= startDateStr && woDate <= endDateStr && !isCancelled;
        });

        filteredWOs.forEach((wo: any) => {
            const parts = wo.partsUsed || wo.partsused || wo.parts || wo.items || [];

            if (Array.isArray(parts)) {
                parts.forEach((part: any) => {
                    // Normalize part ID access
                    const partId = part.partId || part.partid || part.id;
                    const partName = part.partName || part.partname || part.name;
                    const qty = part.quantity || part.qty || 0;

                    // DEBUG: Trace specific product
                    if (partName && partName.toLowerCase().includes("elf")) {
                    }

                    if (partId && partName) {
                        if (!productSales[partId]) {
                            productSales[partId] = {
                                name: partName,
                                quantity: 0,
                            };
                        }
                        productSales[partId].quantity += qty;
                    }
                });
            }
        });


        const result = Object.values(productSales)
            .sort((a, b) => b.quantity - a.quantity)
            .slice(0, 10); // Show top 10

        return result;

    }, [sales, workOrders, reportFilter]);

    // Thống kê work orders (phiếu sửa chữa - lọc theo filter)
    const workOrderStats = useMemo(() => {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = now;

        if (reportFilter.startsWith("month") && reportFilter.length > 5) {
            const monthNum = parseInt(reportFilter.slice(5), 10);
            if (monthNum >= 1 && monthNum <= 12) {
                startDate = new Date(now.getFullYear(), monthNum - 1, 1);
                endDate = new Date(now.getFullYear(), monthNum, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else if (reportFilter.startsWith("q") && reportFilter.length === 2) {
            const quarterNum = parseInt(reportFilter.slice(1), 10);
            if (quarterNum >= 1 && quarterNum <= 4) {
                const startMonth = (quarterNum - 1) * 3;
                startDate = new Date(now.getFullYear(), startMonth, 1);
                endDate = new Date(now.getFullYear(), startMonth + 3, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else {
            switch (reportFilter) {
                case "today":
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                    break;
                case "7days":
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    break;
                case "week":
                    const dayOfWeek = now.getDay();
                    const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
                    startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - diff);
                    break;
                case "month":
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
                    break;
                case "year":
                    startDate = new Date(now.getFullYear(), 0, 1);
                    break;
                default:
                    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        }

        const formatLocalDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        };
        const toLocalDateStr = (dateStr: string | undefined | null): string | null => {
            if (!dateStr) return null;
            try {
                const d = new Date(dateStr);
                if (isNaN(d.getTime())) return null;
                return formatLocalDate(d);
            } catch {
                return null;
            }
        };

        const startDateStr = formatLocalDate(startDate);
        const endDateStr = formatLocalDate(endDate);

        // Filter work orders by date range
        const filteredWOs = (workOrders || []).filter((wo: any) => {
            const woDate = toLocalDateStr(wo.creationDate || wo.creationdate);
            return woDate && woDate >= startDateStr && woDate <= endDateStr;
        });

        const newOrders = filteredWOs.filter(
            (wo) => wo.status === "Tiếp nhận"
        ).length;
        const inProgress = filteredWOs.filter(
            (wo) => wo.status === "Đang sửa"
        ).length;
        const completed = filteredWOs.filter(
            (wo) => wo.status === "Đã sửa xong"
        ).length;
        const delivered = filteredWOs.filter(
            (wo) => wo.status === "Trả máy" || (wo.status as string) === "Đã giao"
        ).length;
        const cancelled = filteredWOs.filter(
            (wo) => (wo.status as string) === "Đã hủy"
        ).length;

        return { newOrders, inProgress, completed, delivered, cancelled };
    }, [workOrders, reportFilter]);

    // DEBUG DATA: Specific audit for "Elf 10W40"
    const debugData = useMemo(() => {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = now;

        if (reportFilter.startsWith("month") && reportFilter.length > 5) {
            const monthNum = parseInt(reportFilter.slice(5), 10);
            if (monthNum >= 1 && monthNum <= 12) {
                startDate = new Date(now.getFullYear(), monthNum - 1, 1);
                endDate = new Date(now.getFullYear(), monthNum, 0);
            } else {
                startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            }
        } else {
            // Default to "month" logic for the user's specific question "from start of month"
            // regardless of filter, but let's stick to the filter if it's set to month
            startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        }

        const formatLocalDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        };
        const toLocalDateStr = (dateStr: string | undefined | null): string | null => {
            if (!dateStr) return null;
            try {
                const d = new Date(dateStr);
                if (isNaN(d.getTime())) return null;
                return formatLocalDate(d);
            } catch {
                return null;
            }
        };

        const startDateStr = formatLocalDate(startDate);
        const endDateStr = formatLocalDate(endDate);

        const transactions: any[] = [];

        // Scan Sales
        sales.forEach(s => {
            const d = toLocalDateStr(s.date);
            if (d && d >= startDateStr && d <= endDateStr) {
            s.items.forEach((item: any) => {
                    const name = item.partName || "";
                    if (name.toLowerCase().includes("elf")) {
                        transactions.push({
                            source: "Bán hàng",
                            id: s.id,
                            code: (s as any).sale_code || "N/A",
                            date: d,
                            product: name,
                            quantity: item.quantity
                        });
                    }
                });
            }
        });

        // Scan Work Orders
        workOrders.forEach(wo => {
            const woAny = wo as any;
            const d = toLocalDateStr(woAny.creationDate || woAny.creationdate);
            const status = ((woAny.status || "") as string).toLowerCase();
            const isCancelled = status === "đã hủy" || status === "cancelled";

            if (!isCancelled && d && d >= startDateStr && d <= endDateStr) {
                const parts = woAny.partsUsed || woAny.partsused || woAny.parts || woAny.items || [];
                if (Array.isArray(parts)) {
                    parts.forEach((part: any) => {
                        const name = part.partName || part.partname || part.name || "";
                        if (name.toLowerCase().includes("elf")) {
                            transactions.push({
                                source: "Sửa chữa",
                                id: woAny.id,
                                code: String(woAny.id || "").slice(0, 8) + "...", // Short ID
                                date: d,
                                product: name,
                                quantity: part.quantity || part.qty || 0
                            });
                        }
                    });
                }
            }
        });

        return transactions;
    }, [sales, workOrders, reportFilter]); // Re-calculate when data changes

    // Cảnh báo
    const alerts = useMemo(() => {
        const warnings: Array<{ type: string; message: string; color: string }> =
            [];

        // Hàng sắp hết
        const lowStockParts = parts.filter(
            (p) => (p.stock[currentBranchId] || 0) < 10
        );
        if (lowStockParts.length > 0) {
            warnings.push({
                type: "Tồn kho thấp",
                message: `${lowStockParts.length} sản phẩm sắp hết hàng`,
                color: "text-orange-600 dark:text-orange-400",
            });
        }

        // Khoản vay đến hạn
        const upcomingLoans = loans.filter((loan) => {
            const daysUntilDue = Math.ceil(
                (new Date(loan.endDate).getTime() - Date.now()) / (1000 * 60 * 60 * 24)
            );
            return daysUntilDue <= 30 && daysUntilDue > 0 && loan.status === "active";
        });
        if (upcomingLoans.length > 0) {
            warnings.push({
                type: "Nợ đến hạn",
                message: `${upcomingLoans.length} khoản vay sắp đến hạn`,
                color: "text-red-600 dark:text-red-400",
            });
        }

        // Số dư thấp
        if (cashBalance + bankBalance < 10000000) {
            warnings.push({
                type: "Số dư thấp",
                message: "Số dư tài khoản dưới 10 triệu",
                color: "text-amber-600 dark:text-amber-400",
            });
        }

        return warnings;
    }, [parts, loans, cashBalance, bankBalance, currentBranchId]);

    // Top Customers Data
    const topCustomersData = useMemo(() => {
        const customerSpending: Record<
            string,
            { name: string; phone?: string; total: number }
        > = {};

        // Tính từ Sales (bán hàng)
        sales.forEach((sale) => {
            const key = sale.customer.phone || sale.customer.name;
            if (!customerSpending[key]) {
                customerSpending[key] = {
                    name: sale.customer.name,
                    phone: sale.customer.phone,
                    total: 0,
                };
            }
            customerSpending[key].total += sale.total;
        });

        // Tính từ Work Orders (phiếu sửa chữa đã thanh toán)
        workOrders.forEach((wo: any) => {
            const isPaid =
                wo.paymentStatus === "paid" ||
                wo.paymentstatus === "paid" ||
                wo.paymentStatus === "partial" ||
                wo.paymentstatus === "partial";

            if (isPaid) {
                const customerName = wo.customerName || wo.customername || "";
                const customerPhone = wo.customerPhone || wo.customerphone || "";
                const key = customerPhone || customerName;

                if (key) {
                    if (!customerSpending[key]) {
                        customerSpending[key] = {
                            name: customerName,
                            phone: customerPhone,
                            total: 0,
                        };
                    }
                    customerSpending[key].total +=
                        wo.totalPaid || wo.totalpaid || wo.total || 0;
                }
            }
        });

        return Object.values(customerSpending)
            .sort((a, b) => b.total - a.total)
            .slice(0, 10);
    }, [sales, workOrders]);

    // Monthly Comparison Data
    const monthlyComparisonData = useMemo(() => {
        const months = [];
        const now = new Date();

        for (let i = 2; i >= 0; i--) {
            const monthDate = new Date(now.getFullYear(), now.getMonth() - i, 1);
            const monthStr = monthDate.toISOString().slice(0, 7); // Format: YYYY-MM
            const monthName = monthDate.toLocaleDateString("vi-VN", {
                month: "short",
                year: "numeric",
            });

            // Tính doanh thu và đơn hàng từ Sales
            const monthSales = sales.filter((s) => {
                if (!s.date) return false;
                const saleMonth = s.date.slice(0, 7);
                return saleMonth === monthStr;
            });
            const salesRevenue = monthSales.reduce((sum, s) => sum + s.total, 0);
            const salesOrders = monthSales.length;

            // Tính doanh thu và đơn hàng từ Work Orders (đã thanh toán)
            const monthWorkOrders = workOrders.filter((wo: any) => {
                // Ưu tiên dùng paymentDate, nếu không có thì dùng creationDate
                const dateRaw =
                    wo.paymentDate ||
                    wo.paymentdate ||
                    wo.creationDate ||
                    wo.creationdate;
                if (!dateRaw) return false;

                const woMonth = dateRaw.slice(0, 7);
                const isPaid =
                    wo.paymentStatus === "paid" ||
                    wo.paymentstatus === "paid" ||
                    wo.paymentStatus === "partial" ||
                    wo.paymentstatus === "partial";
                return woMonth === monthStr && isPaid;
            });
            const woRevenue = monthWorkOrders.reduce(
                (sum, wo: any) => sum + (wo.totalPaid || wo.totalpaid || wo.total || 0),
                0
            );
            const woOrders = monthWorkOrders.length;

            const totalRevenue = salesRevenue + woRevenue;
            const totalOrders = salesOrders + woOrders;

            months.push({
                month: monthName,
                revenue: totalRevenue,
                orders: totalOrders,
            });
        }

        return months;
    }, [sales, workOrders]);

    const ownerInsights = useMemo(() => {
        const normalizeNumber = (value: any) => Number(value || 0);
        const normalizedWorkOrders = (workOrders || []).filter((wo: any) => !wo?.refunded);

        const paidOrders = normalizedWorkOrders.filter((wo: any) => {
            const paymentStatus = wo.paymentStatus || wo.paymentstatus;
            return paymentStatus === "paid" || paymentStatus === "partial";
        });

        const unpaidOrders = normalizedWorkOrders.filter((wo: any) => {
            const remaining = normalizeNumber(wo.remainingAmount ?? wo.remainingamount);
            return remaining > 0;
        });

        const receivables = unpaidOrders.reduce(
            (sum: number, wo: any) => sum + normalizeNumber(wo.remainingAmount ?? wo.remainingamount),
            0
        );

        const openStatuses = ["Tiếp nhận", "Đang sửa", "Đã sửa xong"];
        const openOrders = normalizedWorkOrders.filter((wo: any) =>
            openStatuses.includes(wo.status)
        );

        const openWorkValue = openOrders.reduce(
            (sum: number, wo: any) => sum + normalizeNumber(wo.total),
            0
        );

        const realizedRevenue = paidOrders.reduce(
            (sum: number, wo: any) =>
                sum + normalizeNumber(wo.totalPaid ?? wo.totalpaid ?? wo.total),
            0
        );

        const avgTicketPaid = paidOrders.length > 0 ? realizedRevenue / paidOrders.length : 0;

        const techMap: Record<string, { name: string; jobs: number; revenue: number; openJobs: number }> = {};

        normalizedWorkOrders.forEach((wo: any) => {
            const techName =
                wo.technicianName || wo.technicianname || "Chưa phân công";
            if (!techMap[techName]) {
                techMap[techName] = { name: techName, jobs: 0, revenue: 0, openJobs: 0 };
            }

            techMap[techName].jobs += 1;
            const isOpen = openStatuses.includes(wo.status);
            if (isOpen) {
                techMap[techName].openJobs += 1;
            }

            const paymentStatus = wo.paymentStatus || wo.paymentstatus;
            if (paymentStatus === "paid" || paymentStatus === "partial") {
                techMap[techName].revenue += normalizeNumber(
                    wo.totalPaid ?? wo.totalpaid ?? wo.total
                );
            }
        });

        const topTechnicians = Object.values(techMap)
            .sort((a, b) => b.revenue - a.revenue)
            .slice(0, 5);

        const lowStockParts = (parts || [])
            .map((p: any) => ({
                id: p.id,
                name: p.name,
                stock: normalizeNumber(p.stock?.[currentBranchId] || 0),
            }))
            .filter((p: any) => p.stock <= 10)
            .sort((a: any, b: any) => a.stock - b.stock)
            .slice(0, 8);

        const paymentMix = [
            {
                name: "Đã đủ",
                value: normalizedWorkOrders.filter((wo: any) => (wo.paymentStatus || wo.paymentstatus) === "paid").length,
                color: "#22c55e",
            },
            {
                name: "Một phần",
                value: normalizedWorkOrders.filter((wo: any) => (wo.paymentStatus || wo.paymentstatus) === "partial").length,
                color: "#f59e0b",
            },
            {
                name: "Chưa thu",
                value: normalizedWorkOrders.filter((wo: any) => (wo.paymentStatus || wo.paymentstatus) === "unpaid").length,
                color: "#ef4444",
            },
        ];

        return {
            receivables,
            unpaidOrdersCount: unpaidOrders.length,
            openWorkValue,
            avgTicketPaid,
            topTechnicians,
            lowStockParts,
            paymentMix,
        };
    }, [workOrders, parts, currentBranchId]);

    return {
        todayStats,
        filteredStats,
        topProducts,
        incomeExpenseData,
        last7DaysRevenue,
        workOrderStats,
        alerts,
        cashBalance,
        bankBalance,
        debugData, // EXPORT DEBUG DATA HERE
        ownerInsights,
    };
};

import React, { useEffect, useMemo, useState } from "react";
import { useAppContext } from "../../contexts/AppContext";
import {
  useCashTxRepo,
  useCreateCashTxRepo,
} from "../../hooks/useCashTransactionsRepository";
import { formatCurrency, formatDate } from "../../utils/format";
import { formatCashTxCategory } from "../../lib/finance/cashTxCategories";

const CashBookPage: React.FC = () => {
  const { currentBranchId, paymentSources } = useAppContext();
  const [typeFilter, setTypeFilter] = useState<"all" | "income" | "expense">("all");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [formType, setFormType] = useState<"income" | "expense">("income");
  const [formAmount, setFormAmount] = useState<number>(0);
  const [formCategory, setFormCategory] = useState<string>("other_income");
  const [formDate, setFormDate] = useState<string>(new Date().toISOString().slice(0, 10));
  const [formRecipient, setFormRecipient] = useState<string>("");
  const [formNotes, setFormNotes] = useState<string>("");
  const [formPaymentSourceId, setFormPaymentSourceId] = useState<string>("cash");
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const createCashTxMutation = useCreateCashTxRepo();

  const incomeCategoryOptions = useMemo(
    () => [
      { value: "sale_income", label: "Bán hàng" },
      { value: "service_income", label: "Dịch vụ" },
      { value: "debt_collection", label: "Thu nợ khách hàng" },
      { value: "other_income", label: "Thu khác" },
      { value: "general_income", label: "Thu chung" },
    ],
    []
  );

  const expenseCategoryOptions = useMemo(
    () => [
      { value: "inventory_purchase", label: "Mua hàng" },
      { value: "supplier_payment", label: "Chi trả nhà cung cấp" },
      { value: "salary", label: "Lương nhân viên" },
      { value: "debt_payment", label: "Trả nợ nhà cung cấp" },
      { value: "loan_payment", label: "Trả nợ vay" },
      { value: "other_expense", label: "Chi khác" },
      { value: "general_expense", label: "Chi chung" },
    ],
    []
  );

  const formCategoryOptions = formType === "income" ? incomeCategoryOptions : expenseCategoryOptions;

  useEffect(() => {
    setFormCategory(formType === "income" ? "other_income" : "other_expense");
  }, [formType]);

  const handleCreateCashTx = async () => {
    if (!currentBranchId) return;
    if (!formAmount || formAmount <= 0) return;

    await createCashTxMutation.mutateAsync({
      type: formType,
      amount: Math.max(0, Math.round(formAmount)),
      branchId: currentBranchId,
      paymentSourceId: formPaymentSourceId || "cash",
      date: formDate ? `${formDate}T00:00:00` : undefined,
      category: formCategory,
      recipient: formRecipient.trim() || undefined,
      notes: formNotes.trim() || undefined,
    });

    setFormAmount(0);
    setFormRecipient("");
    setFormNotes("");
    setIsFormModalOpen(false);
  };

  const openTxModal = (type: "income" | "expense") => {
    setFormType(type);
    setIsFormModalOpen(true);
  };

  const queryType = typeFilter === "all" ? undefined : typeFilter;
  const { data: transactions = [], isLoading } = useCashTxRepo({
    branchId: currentBranchId,
    type: queryType,
    startDate: startDate || undefined,
    endDate: endDate || undefined,
  });

  const sortedTx = useMemo(() => {
    return [...transactions].sort(
      (a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime()
    );
  }, [transactions]);

  const summary = useMemo(() => {
    let income = 0;
    let expense = 0;

    for (const tx of sortedTx) {
      const amount = Number(tx.amount || 0);
      if ((tx.type || "").toLowerCase() === "income") {
        income += amount;
      } else {
        expense += amount;
      }
    }

    return {
      income,
      expense,
      balance: income - expense,
    };
  }, [sortedTx]);

  return (
    <div className="p-3 sm:p-5 lg:p-6 bg-slate-50 dark:bg-slate-900 min-h-[calc(100vh-64px)]">
      <div className="max-w-7xl mx-auto bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden">
        <div className="p-4 sm:p-5 lg:p-6 space-y-4 border-b border-slate-200 dark:border-slate-700">
          <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-slate-900 dark:text-slate-100">
                Sổ quỹ
              </h1>
              <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                Theo dõi toàn bộ dòng tiền thu chi theo chi nhánh hiện tại.
              </p>
            </div>
            <div className="flex flex-wrap gap-2 sm:justify-end">
              <button
                onClick={() => openTxModal("income")}
                className="px-3.5 py-2 text-sm rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 shadow-sm"
              >
                + Thêm phiếu Thu
              </button>
              <button
                onClick={() => openTxModal("expense")}
                className="px-3.5 py-2 text-sm rounded-lg bg-red-600 text-white hover:bg-red-700 shadow-sm"
              >
                - Thêm phiếu Chi
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="rounded-lg bg-emerald-50 dark:bg-emerald-900/20 p-3 border border-emerald-100 dark:border-emerald-900/40">
              <div className="text-xs text-emerald-700 dark:text-emerald-300">Tổng thu</div>
              <div className="text-lg font-bold text-emerald-700 dark:text-emerald-300">
                {formatCurrency(summary.income)}
              </div>
            </div>
            <div className="rounded-lg bg-red-50 dark:bg-red-900/20 p-3 border border-red-100 dark:border-red-900/40">
              <div className="text-xs text-red-700 dark:text-red-300">Tổng chi</div>
              <div className="text-lg font-bold text-red-700 dark:text-red-300">
                {formatCurrency(summary.expense)}
              </div>
            </div>
            <div className="rounded-lg bg-blue-50 dark:bg-blue-900/20 p-3 border border-blue-100 dark:border-blue-900/40">
              <div className="text-xs text-blue-700 dark:text-blue-300">Số dư</div>
              <div className="text-lg font-bold text-blue-700 dark:text-blue-300">
                {formatCurrency(summary.balance)}
              </div>
            </div>
          </div>

          <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-2.5 sm:p-3 bg-slate-50 dark:bg-slate-900/40">
            <div className="flex flex-wrap items-center gap-2">
              {[
                { key: "all", label: "Tất cả" },
                { key: "income", label: "Thu" },
                { key: "expense", label: "Chi" },
              ].map((item) => (
                <button
                  key={item.key}
                  onClick={() => setTypeFilter(item.key as "all" | "income" | "expense")}
                  className={`px-3 py-1.5 text-sm rounded-lg border transition ${
                    typeFilter === item.key
                      ? "bg-blue-600 text-white border-blue-600"
                      : "bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 border-slate-300 dark:border-slate-600"
                  }`}
                >
                  {item.label}
                </button>
              ))}

              <div className="h-6 w-px bg-slate-300 dark:bg-slate-600 mx-1 hidden sm:block" />

              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="px-3 py-1.5 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
                title="Từ ngày"
              />
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="px-3 py-1.5 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
                title="Đến ngày"
              />
              <button
                onClick={() => {
                  setStartDate("");
                  setEndDate("");
                  setTypeFilter("all");
                }}
                className="px-3 py-1.5 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700"
              >
                Xóa lọc
              </button>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          {isLoading ? (
            <div className="p-8 text-sm text-slate-500 text-center">Đang tải sổ quỹ...</div>
          ) : sortedTx.length === 0 ? (
            <div className="p-8 text-sm text-slate-500 text-center">Chưa có dữ liệu thu chi.</div>
          ) : (
            <table className="w-full min-w-[900px]">
              <thead className="bg-slate-100 dark:bg-slate-700 sticky top-0 z-10">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-200">Ngày</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-200">Loại</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-200">Danh mục</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-200">Nội dung</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-200">Đối tượng</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-slate-600 dark:text-slate-200">Số tiền</th>
                </tr>
              </thead>
              <tbody>
                {sortedTx.map((tx) => {
                  const isIncome = (tx.type || "").toLowerCase() === "income";
                  return (
                    <tr
                      key={tx.id}
                      className="border-t border-slate-200 dark:border-slate-700 even:bg-slate-50/50 even:dark:bg-slate-800/30 hover:bg-slate-50 dark:hover:bg-slate-700/40"
                    >
                      <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-200">
                        {formatDate(new Date(tx.date), true)}
                      </td>
                      <td className="px-4 py-3 text-sm">
                        <span
                          className={`inline-flex px-2 py-0.5 rounded-full text-xs font-semibold ${
                            isIncome
                              ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
                              : "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300"
                          }`}
                        >
                          {isIncome ? "Thu" : "Chi"}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-200">
                        {formatCashTxCategory((tx as any).category)}
                      </td>
                      <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-200">
                        {(tx as any).notes || (tx as any).description || "-"}
                      </td>
                      <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-200">
                        {(tx as any).recipient || "-"}
                      </td>
                      <td
                        className={`px-4 py-3 text-sm text-right font-semibold ${
                          isIncome
                            ? "text-emerald-700 dark:text-emerald-300"
                            : "text-red-700 dark:text-red-300"
                        }`}
                      >
                        {formatCurrency(Number(tx.amount || 0))}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {isFormModalOpen && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="w-full sm:max-w-xl bg-white dark:bg-slate-800 rounded-t-2xl sm:rounded-2xl border border-slate-200 dark:border-slate-700 shadow-2xl">
            <div className="px-4 py-3 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
              <div className="text-base font-semibold text-slate-900 dark:text-slate-100">
                {formType === "income" ? "Tạo phiếu Thu" : "Tạo phiếu Chi"}
              </div>
              <button
                onClick={() => setIsFormModalOpen(false)}
                className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300"
              >
                ×
              </button>
            </div>

            <div className="p-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
              <select
                value={formCategory}
                onChange={(e) => setFormCategory(e.target.value)}
                className="px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
              >
                {formCategoryOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>

              <input
                type="number"
                min={0}
                value={formAmount || ""}
                onChange={(e) => setFormAmount(Number(e.target.value) || 0)}
                placeholder="Số tiền"
                className="px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
              />

              <input
                type="text"
                value={formRecipient}
                onChange={(e) => setFormRecipient(e.target.value)}
                placeholder="Đối tượng"
                className="px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
              />

              <input
                type="date"
                value={formDate}
                onChange={(e) => setFormDate(e.target.value)}
                className="px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
              />

              <select
                value={formPaymentSourceId}
                onChange={(e) => setFormPaymentSourceId(e.target.value)}
                className="px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
                title="Nguồn tiền"
              >
                {(paymentSources || []).map((source) => (
                  <option key={source.id} value={source.id}>
                    {source.name}
                  </option>
                ))}
                {(paymentSources || []).length === 0 && <option value="cash">Tiền mặt</option>}
              </select>

              <input
                type="text"
                value={formNotes}
                onChange={(e) => setFormNotes(e.target.value)}
                placeholder="Nội dung"
                className="sm:col-span-2 px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200"
              />
            </div>

            <div className="px-4 pb-4 flex gap-2">
              <button
                onClick={() => setIsFormModalOpen(false)}
                className="flex-1 px-3 py-2 text-sm rounded-lg border border-slate-300 dark:border-slate-600"
              >
                Hủy
              </button>
              <button
                onClick={handleCreateCashTx}
                disabled={createCashTxMutation.isPending || formAmount <= 0}
                className={`flex-1 px-3 py-2 text-sm rounded-lg text-white disabled:opacity-50 disabled:cursor-not-allowed ${
                  formType === "income" ? "bg-emerald-600 hover:bg-emerald-700" : "bg-red-600 hover:bg-red-700"
                }`}
              >
                {createCashTxMutation.isPending ? "Đang lưu..." : "Lưu"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CashBookPage;

import React, { useRef, useEffect, useState, useMemo } from "react";
import {
  X,
  Printer,
  Search,
  Check,
  Package,
  Filter,
  Eye,
  ChevronLeft,
  ChevronRight,
  Edit3,
} from "lucide-react";
import JsBarcode from "jsbarcode";
import { Part } from "../../types";
import { formatCurrency } from "../../utils/format";

interface BatchPrintBarcodeModalProps {
  parts: Part[];
  currentBranchId: string;
  onClose: () => void;
  initialQuantities?: Record<string, number>;
}

type BarcodeFormat = "CODE128" | "CODE39";
type LabelPreset = "30x20" | "40x30" | "50x30" | "60x40" | "80x50" | "100x80";
type QuantityMode = "stock" | "fixed" | "custom";
type ViewMode = "select" | "preview";

const LABEL_PRESETS: Record<
  LabelPreset,
  {
    width: number;
    height: number;
    name: string;
    barcodeHeight: number;
    fontSize: number;
  }
> = {
  "30x20": {
    width: 30,
    height: 20,
    name: "30×20mm",
    barcodeHeight: 22,
    fontSize: 10, // Increased from 7
  },
  "40x30": {
    width: 40,
    height: 30,
    name: "40×30mm",
    barcodeHeight: 32,
    fontSize: 12, // Increased from 8
  },
  "50x30": {
    width: 50,
    height: 30,
    name: "50×30mm",
    barcodeHeight: 35,
    fontSize: 13, // Increased from 9
  },
  "60x40": {
    width: 60,
    height: 40,
    name: "60×40mm",
    barcodeHeight: 40,
    fontSize: 14, // Increased from 10
  },
  "80x50": {
    width: 80,
    height: 50,
    name: "80×50mm",
    barcodeHeight: 50,
    fontSize: 16, // Increased from 12
  },
  "100x80": {
    width: 100,
    height: 80,
    name: "100×80mm",
    barcodeHeight: 65,
    fontSize: 18, // Increased from 14
  },
};

// Barcode Preview Component
const BarcodePreview: React.FC<{
  value: string;
  format: BarcodeFormat;
  size: (typeof LABEL_PRESETS)["40x30"];
}> = ({ value, format, size }) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (svgRef.current) {
      try {
        JsBarcode(svgRef.current, value, {
          format: format,
          width: 1.5,
          height: size.barcodeHeight,
          displayValue: true,
          fontSize: size.fontSize,
          margin: 2,
          textMargin: 1,
          font: "monospace",
        });
      } catch {
        JsBarcode(svgRef.current, value, {
          format: "CODE128",
          width: 1.2,
          height: 35,
          displayValue: true,
          fontSize: 8,
          margin: 2,
        });
      }
    }
  }, [value, format, size]);

  return <svg ref={svgRef} className="max-w-full h-auto" />;
};

interface SelectedPart {
  part: Part;
  quantity: number;
}

const BatchPrintBarcodeModal: React.FC<BatchPrintBarcodeModalProps> = ({
  parts,
  currentBranchId,
  onClose,
  initialQuantities,
}) => {
  // View mode
  const [viewMode, setViewMode] = useState<ViewMode>("select");

  // Selection state
  const [selectedParts, setSelectedParts] = useState<Map<string, SelectedPart>>(
    new Map()
  );

  // Initialize from initialQuantities if provided
  useEffect(() => {
    if (initialQuantities && Object.keys(initialQuantities).length > 0) {
      const newSelected = new Map<string, SelectedPart>();
      parts.forEach((part) => {
        const qty = initialQuantities[part.id];
        if (qty !== undefined && qty > 0) {
          newSelected.set(part.id, { part, quantity: qty });
        }
      });
      if (newSelected.size > 0) {
        setSelectedParts(newSelected);
        setQuantityMode("custom");
      }
    }
  }, [parts, initialQuantities]);

  const [searchTerm, setSearchTerm] = useState("");
  const [filterCategory, setFilterCategory] = useState<string>("all");

  // Print settings
  const [labelPreset, setLabelPreset] = useState<LabelPreset>("40x30");
  const [barcodeFormat, setBarcodeFormat] = useState<BarcodeFormat>("CODE128");
  const [showPrice, setShowPrice] = useState(true);
  const [showName, setShowName] = useState(true);
  const [quantityMode, setQuantityMode] = useState<QuantityMode>(
    initialQuantities ? "custom" : "stock"
  );
  const [fixedQuantity, setFixedQuantity] = useState(1);
  const [rotateLabel, setRotateLabel] = useState(false); // Xoay 90° cho cuộn giấy nằm ngang

  // Preview pagination
  const [previewPage, setPreviewPage] = useState(0);
  const labelsPerPage = 6; // Show 6 labels per page in preview

  // Get unique categories
  const categories = useMemo(() => {
    const cats = new Set<string>();
    parts.forEach((p) => {
      if (p.category) cats.add(p.category);
    });
    return Array.from(cats).sort();
  }, [parts]);

  // Filter parts
  const filteredParts = useMemo(() => {
    return parts.filter((p) => {
      const matchSearch =
        !searchTerm ||
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.sku?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.barcode?.toLowerCase().includes(searchTerm.toLowerCase());

      const matchCategory =
        filterCategory === "all" || p.category === filterCategory;

      return matchSearch && matchCategory;
    });
  }, [parts, searchTerm, filterCategory]);

  // Get stock for a part
  const getStock = (part: Part) => part.stock[currentBranchId] || 0;

  // Toggle part selection
  const togglePart = (part: Part) => {
    const newSelected = new Map(selectedParts);
    if (newSelected.has(part.id)) {
      newSelected.delete(part.id);
    } else {
      const qty =
        quantityMode === "stock"
          ? Math.max(1, getStock(part))
          : quantityMode === "fixed"
            ? fixedQuantity
            : 1;
      newSelected.set(part.id, { part, quantity: qty });
    }
    setSelectedParts(newSelected);
  };

  // Select all filtered parts
  const selectAll = () => {
    const newSelected = new Map(selectedParts);
    filteredParts.forEach((part) => {
      if (!newSelected.has(part.id)) {
        const qty =
          quantityMode === "stock"
            ? Math.max(1, getStock(part))
            : quantityMode === "fixed"
              ? fixedQuantity
              : 1;
        newSelected.set(part.id, { part, quantity: qty });
      }
    });
    setSelectedParts(newSelected);
  };

  // Deselect all
  const deselectAll = () => {
    setSelectedParts(new Map());
  };

  // Update quantity for a selected part
  const updateQuantity = (partId: string, quantity: number) => {
    const newSelected = new Map(selectedParts);
    const item = newSelected.get(partId);
    if (item) {
      newSelected.set(partId, { ...item, quantity: Math.max(1, quantity) });
      setSelectedParts(newSelected);
    }
  };

  // Apply quantity mode to all selected
  const applyQuantityMode = () => {
    const newSelected = new Map<string, SelectedPart>();
    selectedParts.forEach((item, id) => {
      const qty =
        quantityMode === "stock"
          ? Math.max(1, getStock(item.part))
          : quantityMode === "fixed"
            ? fixedQuantity
            : item.quantity;
      newSelected.set(id, { ...item, quantity: qty });
    });
    setSelectedParts(newSelected);
  };

  // Total labels count
  const totalLabels = useMemo(() => {
    let total = 0;
    selectedParts.forEach((item) => {
      total += item.quantity;
    });
    return total;
  }, [selectedParts]);

  // Generate all labels for preview
  const allLabels = useMemo(() => {
    const labels: Array<{ part: Part; index: number }> = [];
    selectedParts.forEach(({ part, quantity }) => {
      for (let i = 0; i < quantity; i++) {
        labels.push({ part, index: i });
      }
    });
    return labels;
  }, [selectedParts]);

  // Paginated labels for preview
  const paginatedLabels = useMemo(() => {
    const start = previewPage * labelsPerPage;
    return allLabels.slice(start, start + labelsPerPage);
  }, [allLabels, previewPage, labelsPerPage]);

  const totalPreviewPages = Math.ceil(allLabels.length / labelsPerPage);

  const currentSize = LABEL_PRESETS[labelPreset];

  // Generate barcode SVG string
  const generateBarcodeSVG = (value: string, rotate: boolean = false): string => {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    try {
      JsBarcode(svg, value, {
        format: barcodeFormat,
        width: Math.max(1, (currentSize.width - 10) / 50),
        height: currentSize.barcodeHeight,
        displayValue: true,
        fontSize: currentSize.fontSize,
        margin: 2,
        textMargin: 1,
        font: "monospace",
      });
    } catch {
      JsBarcode(svg, value, {
        format: "CODE128",
        width: 1.2,
        height: 35,
        displayValue: true,
        fontSize: 8,
        margin: 2,
      });
    }

    // Apply rotation directly to SVG if needed
    if (rotate) {
      const svgWidth = svg.getAttribute('width') || '100';
      const svgHeight = svg.getAttribute('height') || '50';
      // Wrap content in a group with rotation transform
      const innerContent = svg.innerHTML;
      svg.innerHTML = `<g transform="rotate(-90, ${parseFloat(svgWidth) / 2}, ${parseFloat(svgHeight) / 2})">${innerContent}</g>`;
      // Swap width and height for rotated SVG
      svg.setAttribute('width', svgHeight);
      svg.setAttribute('height', svgWidth);
      svg.setAttribute('viewBox', `0 0 ${svgHeight} ${svgWidth}`);
    }

    return svg.outerHTML;
  };

  // Handle batch print
  const handlePrint = () => {
    if (selectedParts.size === 0) {
      alert("Vui lòng chọn ít nhất 1 sản phẩm");
      return;
    }

    // Show confirmation with printer settings reminder FIRST
    const confirmed = confirm(
      `⚠️ HƯỚNG DẪN IN MÁY IN NHIỆT XPRINTER\n\n` +
      `📌 QUAN TRỌNG: Khi hộp thoại in xuất hiện:\n` +
      `→ Nhấn Ctrl+Shift+P để mở System Dialog\n` +
      `→ Hoặc bấm "Print using system dialog..."\n\n` +
      `Kích thước nhãn: ${currentSize.width}×${currentSize.height}mm\n\n` +
      `Cài đặt Xprinter (đã cấu hình):\n` +
      `→ Stock: ${currentSize.width}mm × ${currentSize.height}mm\n` +
      `→ Orientation: Portrait/Landscape tùy cuộn giấy\n\n` +
      `Bấm OK để tiếp tục.`
    );

    if (!confirmed) return;

    // Open print window AFTER confirmation
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      alert("Vui lòng cho phép popup để in");
      return;
    }

    // Generate all labels
    let labelsHTML = "";
    selectedParts.forEach(({ part, quantity }) => {
      const barcodeValue = part.barcode || part.sku || part.id.slice(0, 12);
      const barcodeSVG = generateBarcodeSVG(barcodeValue);

      for (let i = 0; i < quantity; i++) {
        // When rotateLabel is true, we keep the content horizontal (no rotation)
        // because the printer will handle the orientation
        // The page size is already swapped (30x40 instead of 40x30)

        labelsHTML += `
          <div class="label">
            <div class="label-content">
              ${showName ? `<div class="label-name">${part.name}</div>` : ""}
              ${barcodeSVG}
              ${showPrice ? `<div class="label-price">${formatCurrency(part.retailPrice[currentBranchId] || 0)}</div>` : ""}
            </div>
          </div>
        `;
      }
    });

    // Calculate dimensions based on rotation
    const pageWidth = rotateLabel ? currentSize.height : currentSize.width;
    const pageHeight = rotateLabel ? currentSize.width : currentSize.height;

    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>In mã vạch hàng loạt - ${selectedParts.size} sản phẩm</title>
          <style>
            @page {
              size: ${pageWidth}mm ${pageHeight}mm;
              margin: 0;
            }
            * { 
              margin: 0; 
              padding: 0; 
              box-sizing: border-box; 
            }
            html, body {
              width: ${pageWidth}mm;
              height: ${pageHeight}mm;
              margin: 0;
              padding: 0;
            }
            body {
              font-family: Arial, sans-serif;
            }
            .label {
              width: ${pageWidth}mm;
              height: ${pageHeight}mm;
              padding: 0;
              display: flex;
              align-items: center;
              justify-content: center;
              box-sizing: border-box;
              overflow: hidden;
              page-break-after: always;
              page-break-inside: avoid;
            }
            .label:last-child {
              page-break-after: avoid;
            }
            .label-content {
              width: ${currentSize.width}mm;
              height: ${currentSize.height}mm;
              padding: 1mm;
              display: flex;
              flex-direction: column;
              align-items: center;
              justify-content: center;
              ${rotateLabel ? 'transform: rotate(-90deg); transform-origin: center center;' : ''}
            }
            .label-name {
              font-size: ${Math.max(7, currentSize.fontSize - 1)}px;
              font-weight: bold;
              text-align: center;
              line-height: 1.2;
              max-width: 100%;
              overflow: hidden;
              display: -webkit-box;
              -webkit-line-clamp: 2;
              -webkit-box-orient: vertical;
              word-break: break-word;
              margin-bottom: 1px;
            }
            .label-price {
              font-size: ${currentSize.fontSize}px;
              font-weight: bold;
              line-height: 1;
              margin-top: 1px;
            }
            svg { 
              max-width: ${currentSize.width - 4}mm !important; 
              height: auto !important; 
            }
            @media print {
              html, body {
                width: ${pageWidth}mm !important;
                height: ${pageHeight}mm !important;
              }
              body { 
                -webkit-print-color-adjust: exact; 
                print-color-adjust: exact; 
              }
              .label-content {
                ${rotateLabel ? `
                  transform: rotate(-90deg) !important;
                  transform-origin: center center !important;
                ` : ''}
              }
            }
            /* Screen only: Show print instructions */
            @media screen {
              .print-info {
                background: #fffbeb;
                border: 2px solid #f59e0b;
                padding: 16px;
                margin: 16px;
                border-radius: 8px;
                font-size: 14px;
                line-height: 1.6;
              }
              .print-info h3 {
                color: #b45309;
                margin-bottom: 8px;
              }
              .print-info code {
                background: #fef3c7;
                padding: 2px 6px;
                border-radius: 4px;
                font-weight: bold;
              }
            }
            @media print {
              .print-info { display: none; }
            }
          </style>
        </head>
        <body>
          <div class="print-info">
            <h3>⚠️ Trước khi in, kiểm tra cài đặt:</h3>
            <p><strong>Khổ giấy:</strong> <code>${currentSize.width}×${currentSize.height}mm</code></p>
            <p><strong>Lề:</strong> Không</p>
            <p><strong>Tỷ lệ:</strong> 100%</p>
            <p style="margin-top:8px">Phần này sẽ không được in ra.</p>
          </div>
          ${labelsHTML}
          <script>
            window.onload = function() {
              setTimeout(function() {
                window.print();
                window.onafterprint = function() { window.close(); };
              }, 500);
            };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-2 md:p-4">
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-200 dark:border-slate-700 shrink-0">
          <div>
            <h2 className="text-lg font-semibold text-slate-900 dark:text-slate-100 flex items-center gap-2">
              <Printer className="w-5 h-5 text-blue-600" />
              In mã vạch hàng loạt
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
              {viewMode === "select"
                ? "Bước 1: Chọn sản phẩm và cài đặt"
                : "Bước 2: Xem trước và chỉnh sửa"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            {/* View Mode Toggle */}
            <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-0.5">
              <button
                onClick={() => setViewMode("select")}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors flex items-center gap-1.5 ${viewMode === "select"
                  ? "bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm"
                  : "text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200"
                  }`}
              >
                <Edit3 className="w-3.5 h-3.5" />
                Chọn SP
              </button>
              <button
                onClick={() => {
                  setViewMode("preview");
                  setPreviewPage(0);
                }}
                disabled={selectedParts.size === 0}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors flex items-center gap-1.5 ${viewMode === "preview"
                  ? "bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-400 shadow-sm"
                  : "text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 disabled:opacity-50 disabled:cursor-not-allowed"
                  }`}
              >
                <Eye className="w-3.5 h-3.5" />
                Xem trước
              </button>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Content */}
        {viewMode === "select" ? (
          /* Selection View */
          <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
            {/* Left: Product Selection */}
            <div className="flex-1 flex flex-col border-r border-slate-200 dark:border-slate-700 overflow-hidden">
              {/* Search & Filter */}
              <div className="p-3 border-b border-slate-200 dark:border-slate-700 space-y-2 shrink-0">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm sản phẩm, SKU, mã vạch..."
                    className="w-full pl-9 pr-3 py-2 text-sm border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100"
                  />
                </div>
                <div className="flex gap-2">
                  <select
                    value={filterCategory}
                    onChange={(e) => setFilterCategory(e.target.value)}
                    className="flex-1 px-3 py-1.5 text-sm border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100"
