﻿import React, { useState, useMemo } from 'react'; // Refresh
import { useQueryClient } from '@tanstack/react-query';
import { showToast } from '../../../utils/toast';
import { supabase } from '../../../supabaseClient';
import { X, Calendar, Search, Filter, DownloadCloud, Trash2, ChevronDown, ChevronUp, Printer, FileText } from 'lucide-react';
import { formatCurrency, formatDate } from '../../../utils/format';
import { InventoryTransaction } from '../../../types';
import InventoryHistorySection from '../InventoryHistorySection';
// Inventory History Modal Component (Ảnh 3)
const InventoryHistoryModal: React.FC<{
  isOpen: boolean;
  onClose: () => void;
  transactions: InventoryTransaction[];
}> = ({ isOpen, onClose, transactions }) => {
  const queryClient = useQueryClient();
  const [activeTimeFilter, setActiveTimeFilter] = useState("7days");
  const [customStartDate, setCustomStartDate] = useState(
    formatDate(new Date(), true)
  );
  const [customEndDate, setCustomEndDate] = useState(
    formatDate(new Date(), true)
  );
  const [searchTerm, setSearchTerm] = useState("");

  const filteredTransactions = useMemo(() => {
    // CHỈ LẤY GIAO DỊCH NHẬP KHO
    let filtered = transactions.filter((t) => t.type === "Nhập kho");
    const now = new Date();

    // Apply time filter
    switch (activeTimeFilter) {
      case "7days":
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        filtered = filtered.filter((t) => new Date(t.date) >= sevenDaysAgo);
        break;
      case "30days":
        const thirtyDaysAgo = new Date(
          now.getTime() - 30 * 24 * 60 * 60 * 1000
        );
        filtered = filtered.filter((t) => new Date(t.date) >= thirtyDaysAgo);
        break;
      case "thisMonth":
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        filtered = filtered.filter((t) => new Date(t.date) >= startOfMonth);
        break;
      case "custom":
        filtered = filtered.filter((t) => {
          const date = new Date(t.date);
          return (
            date >= new Date(customStartDate) && date <= new Date(customEndDate)
          );
        });
        break;
    }

    // Apply search filter
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      filtered = filtered.filter(
        (t) =>
          t.partName.toLowerCase().includes(q) ||
          (t.notes && t.notes.toLowerCase().includes(q))
      );
    }

    return filtered.sort(
      (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  }, [
    transactions,
    activeTimeFilter,
    customStartDate,
    customEndDate,
    searchTerm,
  ]);

  const totalAmount = useMemo(() => {
    return filteredTransactions.reduce((sum, t) => sum + t.totalPrice, 0);
  }, [filteredTransactions]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-slate-800 rounded-lg w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-200 dark:border-slate-700">
          <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100">
            Lịch sử nhập kho
          </h2>
          <button
            onClick={onClose}
            className="text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 text-2xl"
          >
            ×
          </button>
        </div>

        {/* Filters */}
        <div className="p-6 border-b border-slate-200 dark:border-slate-700">
          {/* Time Filter Buttons */}
          <div className="flex flex-wrap gap-2 mb-4">
            {[
              { key: "7days", label: "7 ngày qua" },
              { key: "30days", label: "30 ngày qua" },
              { key: "thisMonth", label: "Tháng này" },
              { key: "custom", label: "Tùy chọn" },
            ].map((filter) => (
              <button
                key={filter.key}
                onClick={() => setActiveTimeFilter(filter.key)}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${activeTimeFilter === filter.key
                  ? "bg-blue-600 text-white"
                  : "bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600"
                  }`}
              >
                {filter.label}
              </button>
            ))}
          </div>

          {/* Custom Date Range */}
          {activeTimeFilter === "custom" && (
            <div className="flex gap-4 mb-4">
              <div className="flex-1">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Từ ngày
                </label>
                <input
                  type="date"
                  value={customStartDate}
                  onChange={(e) => setCustomStartDate(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100"
                />
              </div>
              <div className="flex-1">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Đến ngày
                </label>
                <input
                  type="date"
                  value={customEndDate}
                  onChange={(e) => setCustomEndDate(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100"
                />
              </div>
            </div>
          )}

          {/* Search */}
          <div className="flex gap-4">
            <input
              type="text"
              placeholder="Nhà cung cấp, SKU, tên phụ tùng..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="flex-1 px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100"
            />
          </div>
        </div>

        {/* Summary */}
        <div className="px-6 py-4 bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
          <div className="flex justify-between items-center">
            <div className="text-sm text-slate-600 dark:text-slate-400">
              Tổng số phiếu:{" "}
              <span className="text-lg font-bold text-slate-900 dark:text-slate-100">
                {filteredTransactions.length}
              </span>
            </div>
            <div className="text-right">
              <div className="text-sm text-slate-600 dark:text-slate-400">
                Tổng giá trị
              </div>
              <div className="text-lg font-bold text-blue-600">
                {formatCurrency(totalAmount)}
              </div>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="flex-1 overflow-y-auto">
          <table className="w-full">
            <thead className="bg-slate-100 dark:bg-slate-700 sticky top-0">
              <tr>
                <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                  Ngày
                </th>
                <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                  Nhà cung cấp
                </th>
                <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                  Nội dung
                </th>
                <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                  Số tiền
                </th>
                <th className="text-center px-6 py-3 text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                  Thao tác
                </th>
              </tr>
            </thead>
            <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-200 dark:divide-slate-700">
              {filteredTransactions.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    className="px-6 py-8 text-center text-slate-500"
                  >
                    Không có dữ liệu
                  </td>
                </tr>
              ) : (
                filteredTransactions.map((transaction) => (
                  <tr
                    key={transaction.id}
                    className="hover:bg-slate-50 dark:hover:bg-slate-700/50"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-slate-900 dark:text-slate-100">
                        {formatDate(new Date(transaction.date), false)}
                      </div>
                      <div className="text-xs text-slate-500">
                        {new Date(transaction.date).toLocaleTimeString(
                          "vi-VN",
                          { hour: "2-digit", minute: "2-digit" }
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-slate-900 dark:text-slate-100">
                        {transaction.notes && transaction.notes.includes("NCC:")
                          ? transaction.notes.split("NCC:")[1]?.trim() ||
                          "Chưa rõ"
                          : "Chưa rõ"}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm font-medium text-slate-900 dark:text-slate-100">
                        {transaction.partName}
                      </div>
                      <div className="text-xs text-slate-500">
                        SL: {transaction.quantity}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div className="text-sm font-semibold text-slate-900 dark:text-slate-100">
                        {formatCurrency(transaction.totalPrice)}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-center">
                      <div className="flex items-center justify-center gap-2">
                        <button
                          onClick={() => {
                            // TODO: Implement edit functionality
                            showToast.info("Tính năng đang phát triển");
                          }}
                          className="p-1.5 text-blue-400 hover:bg-blue-500/20 rounded transition-colors"
                          title="Chỉnh sửa"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                            />
                          </svg>
                        </button>
                        <button
                          onClick={async () => {
                            const confirmed = window.confirm(
                              `Bạn có chắc muốn xóa giao dịch nhập "${transaction.partName}"?`
                            );
                            if (confirmed) {
                              try {
                                const { error } = await supabase
                                  .from("inventory_transactions")
                                  .delete()
                                  .eq("id", transaction.id);

                                if (error) throw error;

                                showToast.success("Đã xóa giao dịch");
                                queryClient.invalidateQueries({
                                  queryKey: ["inventoryTransactions"],
                                });
                              } catch (err: any) {
                                showToast.error(
                                  `Lỗi xóa: ${err.message || "Không rõ"}`
                                );
                              }
                            }
                          }}
                          className="p-1.5 text-red-400 hover:bg-red-500/20 rounded transition-colors"
                          title="Xóa"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                            />
                          </svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center">
          <div className="text-sm text-slate-600 dark:text-slate-400">
            Hiển thị {filteredTransactions.length} kết quả
          </div>
        </div>
      </div>
    </div>
  );
};

export default InventoryHistoryModal;

import React, { useState, useMemo } from "react";
import { useAppContext } from "../../contexts/AppContext";
import { formatCurrency, formatDate } from "../../utils/format";
import { usePartsRepoPaged } from "../../hooks/usePartsRepository";
import { getCategoryColor } from "../../utils/categoryColors";

const LookupManager: React.FC = () => {
  const { sales, workOrders, currentBranchId } = useAppContext();

  // Pagination states
  const [page, setPage] = useState(1);
  const [pageSize] = useState(20);

  // Fetch parts data with pagination
  const { data: pagedResult, isLoading } = usePartsRepoPaged({
    page,
    pageSize,
  });
  const parts = pagedResult?.data || [];
  const totalParts = pagedResult?.meta?.total || 0;
  const totalPages = Math.max(1, Math.ceil(totalParts / pageSize));

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [priceRange, setPriceRange] = useState<{
    min: number;
    max: number;
  } | null>(null);
  const [stockFilter, setStockFilter] = useState<
    "all" | "in-stock" | "low-stock" | "out-of-stock"
  >("all");
  const [selectedPart, setSelectedPart] = useState<string | null>(null);

  // Extract categories
  const categories = useMemo(() => {
    const cats = new Set<string>();
    parts.forEach((p) => {
      if (p.category) cats.add(p.category);
    });
    return Array.from(cats).sort();
  }, [parts]);

  // Filter parts
  const filteredParts = useMemo(() => {
    return parts.filter((part) => {
      // Text search
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        const matchName = part.name.toLowerCase().includes(query);
        const matchSku = part.sku?.toLowerCase().includes(query);
        const matchDesc = part.description?.toLowerCase().includes(query);
        if (!matchName && !matchSku && !matchDesc) return false;
      }

      // Category filter
      if (selectedCategory !== "all" && part.category !== selectedCategory) {
        return false;
      }

      // Price filter
      if (priceRange) {
        const price = part.retailPrice[currentBranchId] || 0;
        if (price < priceRange.min || price > priceRange.max) return false;
      }

      // Stock filter
      const stock = part.stock[currentBranchId] || 0;
      if (stockFilter === "in-stock" && stock <= 0) return false;
      if (stockFilter === "low-stock" && stock > 10) return false;
      if (stockFilter === "out-of-stock" && stock > 0) return false;

      return true;
    });
  }, [
    parts,
    searchQuery,
    selectedCategory,
    priceRange,
    stockFilter,
    currentBranchId,
  ]);

  // Get part details with sales history
  const getPartDetails = (partId: string) => {
    const part = parts.find((p) => p.id === partId);
    if (!part) return null;

    // Find sales containing this part
    const partSales = sales.filter((sale) =>
      sale.items.some((item) => item.partId === partId)
    );

    // Find work orders containing this part
    const partWorkOrders = workOrders.filter((wo) =>
      wo.partsUsed?.some((item) => item.partId === partId)
    );

    // Calculate total sold
    const totalSold = partSales.reduce((sum, sale) => {
      const item = sale.items.find((i) => i.partId === partId);
      return sum + (item?.quantity || 0);
    }, 0);

    // Calculate revenue
    const revenue = partSales.reduce((sum, sale) => {
      const item = sale.items.find((i) => i.partId === partId);
      return sum + (item?.sellingPrice || 0) * (item?.quantity || 0);
    }, 0);

    return {
      part,
      salesCount: partSales.length,
      totalSold,
      revenue,
      lastSold:
        partSales.length > 0
          ? partSales.sort(
              (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
            )[0].date
          : null,
      workOrdersCount: partWorkOrders.length,
    };
  };

  const partDetails = selectedPart ? getPartDetails(selectedPart) : null;

  return (
    <div className="h-full flex bg-slate-50 dark:bg-[#0f172a]">
      {/* Left Panel - Search & Filters */}
      <div className="w-96 bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-700 flex flex-col">
        {/* Header */}
        <div className="p-4 border-b border-slate-200 dark:border-slate-700">
          <h1 className="text-xl font-bold text-slate-900 dark:text-slate-100 mb-1">
            Tra cứu sản phẩm
          </h1>
          <p className="text-sm text-slate-600 dark:text-slate-400">
            Tìm kiếm và xem chi tiết sản phẩm
          </p>
        </div>

        {/* Search */}
        <div className="p-4 border-b border-slate-200 dark:border-slate-700">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Tìm theo tên, SKU, mô tả..."
            className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg dark:bg-slate-700 dark:text-slate-100 placeholder-slate-400"
          />
        </div>

        {/* Filters */}
        <div className="flex-1 overflow-auto p-4 space-y-4">
          {/* Category Filter */}
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
              Danh mục
            </label>
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg dark:bg-slate-700 dark:text-slate-100"
            >
              <option value="all">Tất cả danh mục</option>
              {categories.map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>
          </div>

          {/* Stock Filter */}
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
              Tồn kho
            </label>
            <div className="space-y-2">
              {[
                { value: "all", label: "Tất cả" },
                { value: "in-stock", label: "Còn hàng" },
                { value: "low-stock", label: "Sắp hết (≤10)" },
                { value: "out-of-stock", label: "Hết hàng" },
              ].map((option) => (
                <label
                  key={option.value}
                  className="flex items-center gap-2 cursor-pointer"
                >
                  <input
                    type="radio"
                    name="stock"
                    value={option.value}
                    checked={stockFilter === option.value}
                    onChange={(e) =>
                      setStockFilter(
                        e.target.value as
                          | "all"
                          | "in-stock"
                          | "low-stock"
                          | "out-of-stock"
                      )
                    }
                    className="w-4 h-4 text-blue-600"
                  />
                  <span className="text-sm text-slate-700 dark:text-slate-300">
                    {option.label}
                  </span>
                </label>
              ))}
            </div>
          </div>

          {/* Price Range */}
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
              Khoảng giá
            </label>
            <div className="space-y-2">
              <div className="flex gap-2">
                <input
                  type="number"
                  placeholder="Từ"
                  onChange={(e) =>
                    setPriceRange((prev) => ({
                      min: Number(e.target.value) || 0,
                      max: prev?.max || 999999999,
                    }))
                  }
                  className="flex-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg dark:bg-slate-700 dark:text-slate-100 text-sm"
                />
                <input
                  type="number"
                  placeholder="Đến"
                  onChange={(e) =>
                    setPriceRange((prev) => ({
                      min: prev?.min || 0,
                      max: Number(e.target.value) || 999999999,
                    }))
                  }
                  className="flex-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg dark:bg-slate-700 dark:text-slate-100 text-sm"
                />
              </div>
              {priceRange && (
                <button
                  onClick={() => setPriceRange(null)}
                  className="text-xs text-blue-600 dark:text-blue-400 hover:underline"
                >
                  Xóa bộ lọc giá
                </button>
              )}
            </div>
          </div>

          {/* Results Count */}
          <div className="pt-4 border-t border-slate-200 dark:border-slate-700">
            <div className="text-sm text-slate-600 dark:text-slate-400">
              Tìm thấy{" "}
              <span className="font-semibold text-slate-900 dark:text-slate-100">
                {filteredParts.length}
              </span>{" "}
              sản phẩm
            </div>
          </div>
        </div>
      </div>

      {/* Right Panel - Results */}
      <div className="flex-1 flex flex-col">
        {/* Results List */}
        <div className="flex-1 overflow-auto p-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
            {filteredParts.map((part) => {
              const stock = part.stock[currentBranchId] || 0;
              const price = part.retailPrice[currentBranchId] || 0;

              return (
                <div
                  key={part.id}
                  onClick={() => setSelectedPart(part.id)}
                  className={`bg-white dark:bg-[#1e293b] rounded-lg shadow-sm border-2 transition-all cursor-pointer ${
                    selectedPart === part.id
                      ? "border-blue-500 shadow-md"
                      : "border-slate-200 dark:border-slate-700 hover:shadow-md"
                  }`}
                >
                  <div className="p-4">
                    <div className="flex items-start justify-between mb-2">
                      <h3 className="font-semibold text-slate-900 dark:text-slate-100">
                        {part.name}
                      </h3>
                      {stock <= 0 ? (
                        <span className="px-2 py-0.5 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 text-xs rounded">
                          Hết hàng
                        </span>
                      ) : stock <= 10 ? (
                        <span className="px-2 py-0.5 bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 text-xs rounded">
                          Sắp hết
                        </span>
                      ) : (
                        <span className="px-2 py-0.5 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 text-xs rounded">
                          Còn hàng
                        </span>
                      )}
                    </div>

                    <div className="text-xs text-blue-600 dark:text-blue-400 font-mono mb-3">
                      SKU: {part.sku}
                    </div>

                    <div className="flex items-center justify-between">
                      <div>
                        <div className="text-xs text-slate-500 dark:text-slate-400">
                          Tồn kho
                        </div>
                        <div className="text-lg font-bold text-slate-900 dark:text-slate-100">
                          {stock}
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="text-xs text-slate-500 dark:text-slate-400">
                          Giá bán
                        </div>
                        <div className="text-lg font-bold text-blue-600 dark:text-blue-400">
                          {formatCurrency(price)}
                        </div>
                      </div>
                    </div>

                    {part.category && (
                      <div className="mt-3 pt-3 border-t border-slate-200 dark:border-slate-700">
                        <span
                          className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-medium ${
                            getCategoryColor(part.category).bg
                          } ${getCategoryColor(part.category).text}`}
                        >
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2"
                            className="w-3 h-3"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              d="M3 7.5l9-4.5 9 4.5v9l-9 4.5-9-4.5v-9z"
                            />
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              d="M3 7.5l9 4.5 9-4.5"
                            />
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              d="M12 12v9"
                            />
                          </svg>
                          {part.category}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Empty State */}
          {filteredParts.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-center">
              <div className="mb-4 text-slate-400 dark:text-slate-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  className="w-16 h-16"
                >
                  <circle cx="11" cy="11" r="7" />
                  <path d="m21 21-4.35-4.35" />
                </svg>
              </div>
              <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-100 mb-2">
                Không tìm thấy sản phẩm
              </h3>
              <p className="text-slate-600 dark:text-slate-400">
                Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm
              </p>
            </div>
          )}
        </div>

        {/* Pagination Controls */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-slate-200 dark:border-slate-700 bg-white dark:bg-[#1e293b]">
          <div className="text-sm text-slate-600 dark:text-slate-400">
            Trang {page}/{totalPages} • Tổng {totalParts} sản phẩm
          </div>
          <div className="flex items-center gap-2">
            <button
              disabled={page === 1 || isLoading}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="px-3 py-1.5 border border-slate-300 dark:border-slate-600 rounded disabled:opacity-40 hover:bg-slate-50 dark:hover:bg-slate-700"
            >
