                    <div className="flex items-center gap-2">
                      {/* Edit Button */}
                      {po.status !== "received" && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onEdit(po);
                          }}
                          className="p-2.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-amber-100 hover:text-amber-600 dark:hover:bg-amber-900/30 dark:hover:text-amber-400 transition-colors"
                          title="Chỉnh sửa"
                        >
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="20"
                            height="20"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            className="w-5 h-5"
                          >
                            <path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z" />
                            <path d="m15 5 4 4" />
                          </svg>
                        </button>
                      )}

                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onViewDetail(po);
                        }}
                        className="p-2.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-blue-100 hover:text-blue-600 dark:hover:bg-blue-900/30 dark:hover:text-blue-400 transition-colors"
                        title="Xem chi tiết"
                      >
                        <Eye className="w-5 h-5" />
                      </button>
                      {po.status !== "received" && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDelete(po);
                          }}
                          className="p-2.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-red-100 hover:text-red-600 dark:hover:bg-red-900/30 dark:hover:text-red-400 transition-colors"
                          title="Xóa đơn hàng"
                        >
                          <Trash2 className="w-5 h-5" />
                        </button>
                      )}
                    </div>
                  </div>
                </div>

                {/* Notes Footer */}
                {po.notes && (
                  <div className="mt-4 pt-3 border-t border-slate-100 dark:border-slate-700/50 flex items-start gap-2">
                    <FileText className="w-4 h-4 text-slate-400 mt-0.5" />
                    <p className="text-sm text-slate-500 dark:text-slate-400 italic">
                      "{po.notes}"
                    </p>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      <ConfirmModal
        isOpen={confirmState.isOpen}
        title={confirmState.title}
        message={confirmState.message}
        confirmText={confirmState.confirmText}
        cancelText={confirmState.cancelText}
        confirmColor={confirmState.confirmColor}
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </div>
  );
};

import React, { useMemo, useState } from "react";
import { CalendarDays, Coins, HandCoins, TrendingUp, Wallet } from "lucide-react";
import { useDashboardData } from "../dashboard/hooks/useDashboardData";
import { useWorkOrdersRepo } from "../../hooks/useWorkOrdersRepository";
import { usePartsRepo } from "../../hooks/usePartsRepository";
import { useCashTxRepo } from "../../hooks/useCashTransactionsRepository";
import { useAppContext } from "../../contexts/AppContext";
import { calculateFinancialSummary } from "../../lib/reports/financialSummary";
import { formatCurrency } from "../../utils/format";

type FilterKey =
  | "today"
  | "7days"
  | "week"
  | "month"
  | "year"
  | "q1"
  | "q2"
  | "q3"
  | "q4"
  | `month${number}`;

type MetricTab = "revenue" | "cashflow" | "inventory" | "payroll" | "debt" | "tax";

type DailyCashflowRow = {
  dayKey: string;
  income: number;
  expense: number;
  diff: number;
  cashIn: number;
  cashOut: number;
  bankIn: number;
  bankOut: number;
  txCount: number;
};

function toLocalDateKey(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function toDateKeyFromRaw(raw: any): string | null {
  if (!raw) return null;
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return null;
  return toLocalDateKey(d);
}

function isCashSource(sourceId?: string): boolean {
  const normalized = String(sourceId || "").toLowerCase();
  return normalized.includes("cash") || normalized.includes("tienmat");
}

function getFilterRange(filter: FilterKey): { start: Date; end: Date } {
  const now = new Date();
  let start = new Date(now.getFullYear(), now.getMonth(), 1);
  let end = new Date(now.getFullYear(), now.getMonth(), now.getDate());

  if (filter.startsWith("month") && filter.length > 5) {
    const monthNum = Number.parseInt(filter.slice(5), 10);
    if (monthNum >= 1 && monthNum <= 12) {
      start = new Date(now.getFullYear(), monthNum - 1, 1);
      end = new Date(now.getFullYear(), monthNum, 0);
    }
  } else if (filter.startsWith("q") && filter.length === 2) {
    const quarter = Number.parseInt(filter.slice(1), 10);
    const startMonth = Math.max(0, Math.min(3, quarter - 1)) * 3;
    start = new Date(now.getFullYear(), startMonth, 1);
    end = new Date(now.getFullYear(), startMonth + 3, 0);
  } else {
    switch (filter) {
      case "today": {
        start = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        end = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      }
      case "7days": {
        start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      }
      case "week": {
        const dayOfWeek = now.getDay();
        const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
        start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - diff);
        break;
      }
      case "year": {
        start = new Date(now.getFullYear(), 0, 1);
        break;
      }
      default:
        break;
    }
  }

  start.setHours(0, 0, 0, 0);
  end.setHours(23, 59, 59, 999);

  const days = Math.ceil((end.getTime() - start.getTime()) / (24 * 60 * 60 * 1000));
  if (days > 31) {
    start = new Date(end.getTime() - 30 * 24 * 60 * 60 * 1000);
    start.setHours(0, 0, 0, 0);
  }

  return { start, end };
}

export default function ReportsOverview() {
  const [reportFilter, setReportFilter] = useState<FilterKey>("month");
  const [metricTab, setMetricTab] = useState<MetricTab>("revenue");

  const { currentBranchId } = useAppContext();
  const { data: workOrders = [], isLoading: loadingWorkOrders } = useWorkOrdersRepo();
  const { data: parts = [], isLoading: loadingParts } = usePartsRepo();
  const { data: cashTransactions = [], isLoading: loadingCashTx } = useCashTxRepo();

  const { filteredStats } = useDashboardData(reportFilter);

  const metricTabs: Array<{ key: MetricTab; label: string }> = [
    { key: "revenue", label: "Doanh thu" },
    { key: "cashflow", label: "Thu chi" },
    { key: "inventory", label: "Tồn kho" },
    { key: "payroll", label: "Lương" },
    { key: "debt", label: "Công nợ" },
    { key: "tax", label: "Báo cáo thuế" },
  ];

  const quickFilters: Array<{ key: FilterKey; label: string }> = [
    { key: "today", label: "Hôm nay" },
    { key: "7days", label: "7 ngày" },
    { key: "month", label: "Tháng" },
    { key: "q1", label: "Quý" },
    { key: "year", label: "Năm" },
  ];

  const monthFilters = Array.from({ length: 12 }, (_, i) => ({
    key: `month${i + 1}` as FilterKey,
    label: `T${i + 1}`,
  }));

  const dailyRows = useMemo(() => {
    const { start, end } = getFilterRange(reportFilter);
    const rows: Array<{
      dayKey: string;
      salesRevenue: number;
      serviceRevenue: number;
      totalRevenue: number;
      grossProfit: number;
      otherExpense: number;
      netProfit: number;
      workOrderCount: number;
      otherTxCount: number;
    }> = [];

    for (let cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
      const dayStart = new Date(cursor);
      dayStart.setHours(0, 0, 0, 0);
      const dayEnd = new Date(cursor);
      dayEnd.setHours(23, 59, 59, 999);

      const summary = calculateFinancialSummary({
        sales: [],
        workOrders,
        parts,
        cashTransactions,
        branchId: currentBranchId,
        start: dayStart,
        end: dayEnd,
      });

      const dayKey = toLocalDateKey(dayStart);
      const workOrderCount = summary.filteredWorkOrders.length;
      const otherTxCount = (cashTransactions || []).filter((tx: any) => {
        const txDay = toDateKeyFromRaw(tx.date);
        return txDay === dayKey;
      }).length;

      rows.push({
        dayKey,
        salesRevenue: summary.salesRevenue,
        serviceRevenue: summary.woRevenue,
        totalRevenue: summary.combinedRevenue,
        grossProfit: summary.totalProfit,
        otherExpense: summary.cashExpense,
        netProfit: summary.netProfit,
        workOrderCount,
        otherTxCount,
      });
    }

    return rows.reverse();
  }, [reportFilter, workOrders, parts, cashTransactions, currentBranchId]);

  const dailyCashflowRows = useMemo<DailyCashflowRow[]>(() => {
    const { start, end } = getFilterRange(reportFilter);
    const rowsMap = new Map<string, DailyCashflowRow>();

    for (let cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
      const day = new Date(cursor);
      day.setHours(0, 0, 0, 0);
      const dayKey = toLocalDateKey(day);
      rowsMap.set(dayKey, {
        dayKey,
        income: 0,
        expense: 0,
        diff: 0,
        cashIn: 0,
        cashOut: 0,
        bankIn: 0,
        bankOut: 0,
        txCount: 0,
      });
    }

    (cashTransactions || []).forEach((tx: any) => {
      const txDay = toDateKeyFromRaw(tx.date);
      if (!txDay || !rowsMap.has(txDay)) return;

      const txBranch = tx.branchId || tx.branchid || tx.branch_id;
      if (currentBranchId && txBranch && txBranch !== currentBranchId) return;

      const row = rowsMap.get(txDay)!;
      const amount = Number(tx.amount || 0);
      const isCash = isCashSource(tx.paymentSourceId || tx.paymentsource || tx.paymentSource);
      const txType = tx.type === "income" ? "income" : "expense";

      if (txType === "income") {
        row.income += amount;
        if (isCash) row.cashIn += amount;
        else row.bankIn += amount;
      } else {
        row.expense += amount;
        if (isCash) row.cashOut += amount;
        else row.bankOut += amount;
      }

      row.txCount += 1;
    });

    return Array.from(rowsMap.values())
      .map((row) => ({
        ...row,
        diff: row.income - row.expense,
      }))
      .reverse();
  }, [cashTransactions, currentBranchId, reportFilter]);

  const cashflowTotals = useMemo(() => {
    return dailyCashflowRows.reduce(
      (acc, row) => {
        acc.income += row.income;
        acc.expense += row.expense;
        acc.diff += row.diff;
        acc.cashIn += row.cashIn;
        acc.bankIn += row.bankIn;
        return acc;
      },
      { income: 0, expense: 0, diff: 0, cashIn: 0, bankIn: 0 }
    );
  }, [dailyCashflowRows]);

  const isLoading = loadingWorkOrders || loadingParts || loadingCashTx;

  return (
    <div className="space-y-4 md:space-y-5">
      <section className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
        <div className="flex flex-wrap items-center gap-2">
          {metricTabs.map((tab) => (
            <button
              key={tab.key}
              type="button"
              onClick={() => setMetricTab(tab.key)}
              className={`rounded-xl px-3 py-2 text-sm font-semibold transition ${
                metricTab === tab.key
                  ? "bg-blue-600 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-2">
          {quickFilters.map((item) => (
            <button
              key={item.key}
              type="button"
              onClick={() => setReportFilter(item.key)}
              className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition ${
                reportFilter === item.key
                  ? "bg-blue-600 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700"
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div className="mt-2 flex flex-wrap items-center gap-1.5">
          {monthFilters.map((item) => (
            <button
              key={item.key}
              type="button"
              onClick={() => setReportFilter(item.key)}
              className={`rounded-md px-2.5 py-1 text-xs font-semibold transition ${
                reportFilter === item.key
                  ? "bg-blue-600 text-white"
                  : "bg-slate-100 text-slate-500 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700"
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </section>

      {metricTab === "cashflow" ? (
        <section className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-5">
          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <Coins className="h-4 w-4" /> Thu trong kỳ
            </div>
            <div className="mt-2 text-2xl font-bold text-emerald-500">
              {formatCurrency(cashflowTotals.income)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <Wallet className="h-4 w-4" /> Chi trong kỳ
            </div>
            <div className="mt-2 text-2xl font-bold text-rose-500">
              {formatCurrency(cashflowTotals.expense)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <TrendingUp className="h-4 w-4" /> Chênh lệch
            </div>
            <div
              className={`mt-2 text-2xl font-bold ${
                cashflowTotals.diff >= 0 ? "text-emerald-500" : "text-rose-500"
              }`}
            >
              {formatCurrency(cashflowTotals.diff)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <HandCoins className="h-4 w-4" /> TM trong kỳ
            </div>
            <div className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
              {formatCurrency(cashflowTotals.cashIn)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <HandCoins className="h-4 w-4" /> NH trong kỳ
            </div>
            <div className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
              {formatCurrency(cashflowTotals.bankIn)}
            </div>
          </article>
        </section>
      ) : (
        <section className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-4">
          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <Coins className="h-4 w-4" /> Tổng doanh thu
            </div>
            <div className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
              {formatCurrency(filteredStats.revenue)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <Wallet className="h-4 w-4" /> Tổng chi phí
            </div>
            <div className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
              {formatCurrency(filteredStats.expense)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <TrendingUp className="h-4 w-4" /> Lợi nhuận thuần
            </div>
            <div
              className={`mt-2 text-2xl font-bold ${
                filteredStats.profit >= 0 ? "text-emerald-500" : "text-rose-500"
              }`}
            >
              {formatCurrency(filteredStats.profit)}
            </div>
          </article>

          <article className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
            <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
              <HandCoins className="h-4 w-4" /> Tỷ suất lợi nhuận
            </div>
            <div className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">
              {filteredStats.revenue > 0
                ? ((filteredStats.profit / filteredStats.revenue) * 100).toFixed(1)
                : "0.0"}
              %
            </div>
          </article>
        </section>
      )}

      <section className="rounded-2xl border border-slate-200/70 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900/70">
        <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-slate-800 dark:text-slate-100">
          <CalendarDays className="h-4 w-4 text-blue-500" />
          {metricTab === "cashflow" ? "Thu chi theo ngày" : "Chi tiết theo ngày"}
        </div>

        {isLoading ? (
          <div className="py-12 text-center text-sm text-slate-500 dark:text-slate-400">
            Đang tải dữ liệu báo cáo...
          </div>
        ) : metricTab === "cashflow" ? (
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead>
                <tr className="border-b border-slate-200 text-left text-xs uppercase tracking-wide text-slate-500 dark:border-slate-700 dark:text-slate-400">
                  <th className="px-3 py-2">Ngày</th>
                  <th className="px-3 py-2">Thu</th>
                  <th className="px-3 py-2">Chi</th>
                  <th className="px-3 py-2">Chênh lệch</th>
                  <th className="px-3 py-2">TM thu/chi</th>
                  <th className="px-3 py-2">NH thu/chi</th>
                  <th className="px-3 py-2">Số GD</th>
                </tr>
              </thead>
              <tbody>
                {dailyCashflowRows.map((row) => (
                  <tr key={row.dayKey} className="border-b border-slate-100 dark:border-slate-800">
                    <td className="px-3 py-2 font-semibold text-slate-700 dark:text-slate-200">
                      {row.dayKey}
                    </td>
                    <td className="px-3 py-2 text-emerald-500 font-semibold">
                      {formatCurrency(row.income)}
                    </td>
                    <td className="px-3 py-2 text-rose-500 font-semibold">
                      {formatCurrency(row.expense)}
                    </td>
                    <td
                      className={`px-3 py-2 font-bold ${
                        row.diff >= 0 ? "text-emerald-500" : "text-rose-500"
                      }`}
                    >
                      {formatCurrency(row.diff)}
                    </td>
                    <td className="px-3 py-2 text-slate-600 dark:text-slate-300">
                      {formatCurrency(row.cashIn)} / {formatCurrency(row.cashOut)}
                    </td>
                    <td className="px-3 py-2 text-slate-600 dark:text-slate-300">
                      {formatCurrency(row.bankIn)} / {formatCurrency(row.bankOut)}
                    </td>
                    <td className="px-3 py-2 text-slate-500 dark:text-slate-400">
                      {row.txCount}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead>
                <tr className="border-b border-slate-200 text-left text-xs uppercase tracking-wide text-slate-500 dark:border-slate-700 dark:text-slate-400">
                  <th className="px-3 py-2">Ngày</th>
                  <th className="px-3 py-2">Bán hàng</th>
                  <th className="px-3 py-2">Sửa chữa</th>
                  <th className="px-3 py-2">Doanh thu tổng</th>
                  <th className="px-3 py-2">Lãi gộp</th>
                  <th className="px-3 py-2">Chi phí khác</th>
                  <th className="px-3 py-2">Lãi ròng</th>
                  <th className="px-3 py-2">Số giao dịch</th>
                </tr>
              </thead>
              <tbody>
                {dailyRows.map((row) => (
                  <tr key={row.dayKey} className="border-b border-slate-100 dark:border-slate-800">
                    <td className="px-3 py-2 font-semibold text-slate-700 dark:text-slate-200">
                      {row.dayKey}
                    </td>
                    <td className="px-3 py-2 text-slate-600 dark:text-slate-300">
                      {formatCurrency(row.salesRevenue)}
                    </td>
                    <td className="px-3 py-2 text-slate-600 dark:text-slate-300">
                      {formatCurrency(row.serviceRevenue)}
                    </td>
                    <td className="px-3 py-2 font-semibold text-slate-700 dark:text-slate-200">
                      {formatCurrency(row.totalRevenue)}
                    </td>
                    <td className="px-3 py-2 text-emerald-500">
                      {formatCurrency(row.grossProfit)}
                    </td>
                    <td className="px-3 py-2 text-rose-500">
                      {formatCurrency(row.otherExpense)}
                    </td>
                    <td
                      className={`px-3 py-2 font-bold ${
                        row.netProfit >= 0 ? "text-emerald-500" : "text-rose-500"
                      }`}
                    >
                      {formatCurrency(row.netProfit)}
                    </td>
                    <td className="px-3 py-2 text-slate-500 dark:text-slate-400">
                      {row.workOrderCount + row.otherTxCount}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import {
  Search,
  ShoppingCart,
  Trash2,
  Plus,
  Minus,
  User,
  ReceiptText,
  Printer,
  RefreshCcw,
  ArrowLeft,
  ArrowRight,
} from "lucide-react";
import { useAppContext } from "../../contexts/AppContext";
import { formatCurrency } from "../../utils/format";
import { showToast } from "../../utils/toast";
import type { CartItem, Part } from "../../types";
import { useCustomers } from "../../hooks/useSupabase";
import { usePartsRepo } from "../../hooks/usePartsRepository";

type UiMode = "enterprise" | "retail" | "dark";

const getBranchStock = (part: Part, branchId: string): number => {
  const stock = Math.max(0, Number(part.stock?.[branchId] || 0));
  const reserved = Math.max(0, Number(part.reservedStock?.[branchId] || 0));
  return Math.max(0, stock - reserved);
};

const getBranchRetailPrice = (part: Part, branchId: string): number =>
  Math.max(0, Number(part.retailPrice?.[branchId] || 0));

const SalesManager: React.FC = () => {
  const {
    parts,
    customers,
    cartItems,
    setCartItems,
    setParts,
    currentBranchId,
    finalizeSale,
    deleteSale,
    sales,
  } = useAppContext();
  const { data: customersFromRepo = [] } = useCustomers();
  const {
    data: partsFromRepo = [],
    isSuccess: partsLoaded,
    isFetching: syncingInventory,
    refetch: refetchParts,
  } = usePartsRepo();

  const [search, setSearch] = useState("");
  const [customerSearch, setCustomerSearch] = useState("Khách lẻ");
  const [customerName, setCustomerName] = useState("Khách lẻ");
  const [customerPhone, setCustomerPhone] = useState("");
  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<"cash" | "bank">("cash");
  const [note, setNote] = useState("");
  const [showCustomerSuggestions, setShowCustomerSuggestions] = useState(false);
  const [autoPrintInvoice, setAutoPrintInvoice] = useState(true);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(12);
  const [historyQuery, setHistoryQuery] = useState("");
  const [historyPage, setHistoryPage] = useState(1);
  const [rightTab, setRightTab] = useState<"checkout" | "history">("checkout");
  const [mobileStep, setMobileStep] = useState<"products" | "checkout">(
    "products"
  );
  const [uiMode, setUiMode] = useState<UiMode>(() => {
    try {
      const saved = localStorage.getItem("sales-ui-mode") as UiMode | null;
      if (saved === "enterprise") return "retail";
      return saved || "retail";
    } catch {
      return "retail";
    }
  });

  const inventoryParts = parts;

  const customerSource = useMemo(() => {
    if (customersFromRepo.length) return customersFromRepo;
    return customers;
  }, [customersFromRepo, customers]);

  const customerSuggestions = useMemo(() => {
    const keyword = customerSearch.trim().toLowerCase();
    if (!keyword) return customerSource.slice(0, 8);
    return customerSource
      .filter((c) => {
        const name = (c.name || "").toLowerCase();
        const phone = (c.phone || "").toLowerCase();
        return name.includes(keyword) || phone.includes(keyword);
      })
      .slice(0, 8);
  }, [customerSource, customerSearch]);

  const filteredParts = useMemo(() => {
    const keyword = search.trim().toLowerCase();
    return inventoryParts
      .filter((part) => {
        const hasStock = getBranchStock(part, currentBranchId) > 0;
        const hasWarranty = Boolean(String(part.warrantyPeriod || "").trim());
        return hasStock || hasWarranty;
      })
      .filter((part) => {
        if (!keyword) return true;
        return (
          part.name.toLowerCase().includes(keyword) ||
          part.sku.toLowerCase().includes(keyword) ||
          (part.barcode || "").toLowerCase().includes(keyword)
        );
      })
      .sort((a, b) => a.name.localeCompare(b.name, "vi"));
  }, [inventoryParts, currentBranchId, search]);

  const totalPages = Math.max(1, Math.ceil(filteredParts.length / pageSize));

  useEffect(() => {
    setPage(1);
  }, [search, currentBranchId, pageSize]);

  useEffect(() => {
    if (!partsLoaded) return;
    setParts(partsFromRepo);
  }, [partsLoaded, partsFromRepo, setParts]);

  useEffect(() => {
    try {
      localStorage.setItem("sales-ui-mode", uiMode);
    } catch {
      // ignore storage errors
    }
  }, [uiMode]);

  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [page, totalPages]);

  useEffect(() => {
    setHistoryPage(1);
  }, [historyQuery, sales.length]);

  useEffect(() => {
    if (cartItems.length === 0 && mobileStep === "checkout") {
      setMobileStep("products");
    }
  }, [cartItems.length, mobileStep]);

  const pagedParts = useMemo(() => {
    const start = (page - 1) * pageSize;
    return filteredParts.slice(start, start + pageSize);
  }, [filteredParts, page, pageSize]);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.sellingPrice * item.quantity, 0),
    [cartItems]
  );

  const total = Math.max(0, subtotal - discount);

  const printInvoice = (payload: {
    customer: { name: string; phone?: string };
    items: CartItem[];
    subtotalValue: number;
    discountValue: number;
    totalValue: number;
    payment: "cash" | "bank";
    noteText?: string;
  }) => {
    const w = window.open("", "_blank", "width=420,height=700");
    if (!w) {
      showToast.warning("Trình duyệt đang chặn cửa sổ in hóa đơn.");
      return;
    }

    const rows = payload.items
      .map(
        (it) => `
          <tr>
            <td>${it.partName}</td>
            <td style="text-align:center">${it.quantity}</td>
            <td style="text-align:right">${formatCurrency(it.sellingPrice)}</td>
            <td style="text-align:right">${formatCurrency(it.sellingPrice * it.quantity)}</td>
          </tr>`
      )
      .join("");

    w.document.write(`<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Hóa đơn bán hàng</title>
  <style>
    body { font-family: Arial, Helvetica, sans-serif; padding: 16px; color: #0f172a; }
    h1 { margin: 0 0 8px; font-size: 18px; }
    .meta { font-size: 12px; margin-bottom: 10px; color: #334155; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th, td { border-bottom: 1px dashed #cbd5e1; padding: 6px 4px; }
    th { text-align: left; }
    .sum { margin-top: 10px; font-size: 13px; }
    .sum-row { display: flex; justify-content: space-between; margin: 3px 0; }
    .total { font-weight: 700; font-size: 15px; margin-top: 5px; }
  </style>
</head>
<body>
  <h1>Hóa đơn bán hàng</h1>
  <div class="meta">Ngày giờ: ${new Date().toLocaleString("vi-VN")}</div>
  <div class="meta">Khách hàng: ${payload.customer.name}${payload.customer.phone ? ` - ${payload.customer.phone}` : ""}</div>
  <div class="meta">Thanh toán: ${payload.payment === "cash" ? "Tiền mặt" : "Chuyển khoản"}</div>
  <table>
    <thead>
      <tr>
        <th>Sản phẩm</th>
        <th style="text-align:center">SL</th>
        <th style="text-align:right">Đơn giá</th>
        <th style="text-align:right">Thành tiền</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  <div class="sum">
    <div class="sum-row"><span>Tạm tính</span><span>${formatCurrency(payload.subtotalValue)}</span></div>
    <div class="sum-row"><span>Giảm giá</span><span>- ${formatCurrency(payload.discountValue)}</span></div>
    <div class="sum-row total"><span>Thanh toán</span><span>${formatCurrency(payload.totalValue)}</span></div>
  </div>
  ${payload.noteText ? `<div class="meta">Ghi chú: ${payload.noteText}</div>` : ""}
</body>
</html>`);
    w.document.close();
    w.focus();
    w.print();
    w.close();
  };

  const syncInventory = async () => {
    const result = await refetchParts();
    const next = result.data || partsFromRepo;
    if (next?.length) {
      setParts(next);
      showToast.success("Đã đồng bộ tồn kho mới nhất từ dữ liệu kho.");
      return;
    }
    showToast.warning("Không lấy được dữ liệu kho để đồng bộ.");
  };

  const addPartToCart = (part: Part) => {
    const branchStock = getBranchStock(part, currentBranchId);

    setCartItems((prev) => {
      const existing = prev.find((item) => item.partId === part.id);
      const existingQty = existing?.quantity || 0;

      if (existingQty >= branchStock) {
        showToast.warning(`Tồn kho còn ${branchStock}, không thể thêm thêm.`);
        return prev;
      }

      if (existing) {
        return prev.map((item) =>
          item.partId === part.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }

      const newItem: CartItem = {
        partId: part.id,
        partName: part.name,
        sku: part.sku,
        category: part.category,
        quantity: 1,
        sellingPrice: getBranchRetailPrice(part, currentBranchId),
        stockSnapshot: branchStock,
      };

      return [...prev, newItem];
    });
  };

  const updateQty = (partId: string, nextQty: number) => {
    if (nextQty <= 0) {
      setCartItems((prev) => prev.filter((item) => item.partId !== partId));
      return;
    }

    setCartItems((prev) =>
      prev.map((item) => {
        if (item.partId !== partId) return item;
        if (nextQty > item.stockSnapshot) {
          showToast.warning(`Tồn kho chỉ còn ${item.stockSnapshot}.`);
          return item;
        }
        return { ...item, quantity: nextQty };
      })
    );
  };

  const removeItem = (partId: string) => {
    setCartItems((prev) => prev.filter((item) => item.partId !== partId));
  };

  const submitSale = () => {
    if (!cartItems.length) {
      showToast.warning("Giỏ hàng đang trống.");
      return;
    }

    if (!customerName.trim()) {
      showToast.warning("Vui lòng nhập tên khách hàng.");
      return;
    }

    if (discount < 0 || discount > subtotal) {
      showToast.warning("Giảm giá không hợp lệ.");
      return;
    }

    for (const item of cartItems) {
      const part = inventoryParts.find((p) => p.id === item.partId);
      const availableStock = part ? getBranchStock(part, currentBranchId) : 0;
      if (item.quantity > availableStock) {
        showToast.warning(`Sản phẩm ${item.partName} không đủ tồn (${availableStock}).`);
        return;
      }
    }

    const payload = {
      customer: {
        name: customerName.trim(),
        phone: customerPhone.trim() || undefined,
      },
      items: cartItems,
      subtotalValue: subtotal,
      discountValue: discount,
      totalValue: total,
      payment: paymentMethod,
      noteText: note.trim() || undefined,
    } as const;

    finalizeSale({
      items: cartItems,
      discount,
      paymentMethod,
      customer: payload.customer,
      note: note.trim() || undefined,
    });

    setDiscount(0);
    setNote("");
    setMobileStep("products");
    if (autoPrintInvoice) {
      printInvoice(payload);
    }
    showToast.success("Đã tạo phiếu bán hàng thành công.");
  };

  const handleDeleteSale = (saleId: string) => {
    const targetSale = sales.find((sale) => sale.id === saleId);
    if (!targetSale) {
      showToast.warning("Không tìm thấy phiếu bán hàng để xóa.");
      return;
    }

    const ok = window.confirm(
      `Xóa phiếu ${saleId}?\nHệ thống sẽ hoàn lại tồn kho và hoàn tiền về nguồn thanh toán.`
    );
    if (!ok) return;

    deleteSale(saleId);
  };

  const historyPageSize = 6;

  const filteredSalesHistory = useMemo(() => {
    const keyword = historyQuery.trim().toLowerCase();
    const normalized = sales.filter((sale) => {
      if (!keyword) return true;
      const customerName = (sale.customer?.name || "").toLowerCase();
      const customerPhone = (sale.customer?.phone || "").toLowerCase();
      const saleId = (sale.id || "").toLowerCase();
      return (
        customerName.includes(keyword) ||
        customerPhone.includes(keyword) ||
        saleId.includes(keyword)
      );
    });
    return normalized.slice(0, 200);
  }, [sales, historyQuery]);

  const totalHistoryPages = Math.max(
    1,
    Math.ceil(filteredSalesHistory.length / historyPageSize)
  );

  useEffect(() => {
    if (historyPage > totalHistoryPages) {
      setHistoryPage(totalHistoryPages);
    }
  }, [historyPage, totalHistoryPages]);

  const pagedSalesHistory = useMemo(() => {
    const start = (historyPage - 1) * historyPageSize;
    return filteredSalesHistory.slice(start, start + historyPageSize);
  }, [filteredSalesHistory, historyPage]);

  const ui = useMemo(() => {
    if (uiMode === "retail") {
      return {
        pageBg:
          "w-full px-3 md:px-6 py-4 md:py-6 bg-[radial-gradient(circle_at_top_left,_rgba(249,115,22,0.14),_transparent_34%),radial-gradient(circle_at_top_right,_rgba(236,72,153,0.14),_transparent_34%),linear-gradient(180deg,#fff7ed_0%,#fff1f2_100%)] dark:bg-[radial-gradient(circle_at_top_left,_rgba(249,115,22,0.16),_transparent_34%),radial-gradient(circle_at_top_right,_rgba(236,72,153,0.16),_transparent_34%),linear-gradient(180deg,#1f2937_0%,#111827_100%)]",
        header:
          "mb-4 md:mb-6 rounded-2xl border border-orange-200/60 dark:border-orange-500/30 bg-white/80 dark:bg-slate-900/70 backdrop-blur-md shadow-sm px-4 md:px-6 py-4 flex flex-wrap items-center justify-between gap-3",
        leftPanel:
          "xl:col-span-2 bg-white/90 dark:bg-slate-900/80 backdrop-blur-md rounded-2xl border border-orange-200/70 dark:border-orange-500/30 overflow-hidden shadow-sm",
        rightPanel:
          "bg-white/90 dark:bg-slate-900/85 rounded-2xl border border-orange-200/70 dark:border-orange-500/30 p-4 md:p-5 space-y-4 shadow-sm xl:sticky xl:top-24 h-fit",
        panelHead:
          "p-4 border-b border-orange-200/60 dark:border-orange-500/30 flex items-center justify-between gap-3 bg-gradient-to-r from-orange-50 to-pink-50 dark:from-slate-900 dark:to-slate-800",
        rowHover: "border-t border-slate-100 dark:border-slate-700 hover:bg-orange-50/60 dark:hover:bg-slate-800/70 transition",
        stockBadge:
          "inline-flex items-center rounded-full px-2 py-0.5 text-xs font-semibold bg-orange-100 text-orange-700 dark:bg-orange-500/20 dark:text-orange-300",
        addBtn:
          "inline-flex items-center gap-1.5 h-9 px-3 rounded-lg bg-gradient-to-r from-orange-500 to-pink-500 hover:from-orange-600 hover:to-pink-600 text-white shadow-sm hover:shadow transition",
        syncBtn:
          "h-10 px-3 rounded-xl border border-orange-300 dark:border-orange-500/40 text-orange-700 dark:text-orange-200 hover:bg-orange-50 dark:hover:bg-orange-500/10 disabled:opacity-50 transition",
        summary: "rounded-xl bg-orange-50/70 dark:bg-orange-500/10 border border-orange-200/70 dark:border-orange-500/30 p-3 space-y-1 text-sm",
      };
    }

    if (uiMode === "dark") {
      return {
        pageBg:
          "w-full px-3 md:px-6 py-4 md:py-6 bg-[radial-gradient(circle_at_top_left,_rgba(56,189,248,0.16),_transparent_34%),radial-gradient(circle_at_top_right,_rgba(168,85,247,0.18),_transparent_34%),linear-gradient(180deg,#020617_0%,#0f172a_100%)]",
        header:
          "mb-4 md:mb-6 rounded-2xl border border-sky-500/20 bg-slate-900/60 backdrop-blur-xl shadow-[0_20px_45px_-25px_rgba(14,165,233,0.45)] px-4 md:px-6 py-4 flex flex-wrap items-center justify-between gap-3",
        leftPanel:
          "xl:col-span-2 bg-slate-900/65 backdrop-blur-xl rounded-2xl border border-sky-500/20 overflow-hidden shadow-[0_20px_45px_-25px_rgba(14,165,233,0.35)]",
        rightPanel:
          "bg-slate-900/65 rounded-2xl border border-sky-500/20 p-4 md:p-5 space-y-4 shadow-[0_20px_45px_-25px_rgba(14,165,233,0.35)] xl:sticky xl:top-24 h-fit",
        panelHead:
          "p-4 border-b border-sky-500/20 flex items-center justify-between gap-3 bg-gradient-to-r from-slate-900/70 to-slate-800/40",
        rowHover: "border-t border-slate-700/70 hover:bg-sky-500/10 transition",
        stockBadge:
          "inline-flex items-center rounded-full px-2 py-0.5 text-xs font-semibold bg-sky-500/20 text-sky-300",
        addBtn:
          "inline-flex items-center gap-1.5 h-9 px-3 rounded-lg bg-gradient-to-r from-sky-500 to-indigo-500 hover:from-sky-400 hover:to-indigo-400 text-white shadow-sm hover:shadow transition",
