                      0
                    ) || 0;
                  const servicesCostPrice =
                    order.additionalServices?.reduce(
                      (sum: number, s: any) =>
                        sum + (s.costPrice || 0) * (s.quantity || 1),
                      0
                    ) || 0;
                  const orderProfit =
                    totalAmount - partsCostPrice - servicesCostPrice;

                  const paymentPillClass =
                    order.paymentStatus === "paid"
