                              <Settings className="w-3.5 h-3.5 text-slate-400 mt-0.5 flex-shrink-0" />
                              <span className="text-slate-700 dark:text-slate-300 line-clamp-1">
                                {servicesSummary}
                                {servicesSuffix && (
                                  <span className="text-slate-400">
                                    {servicesSuffix}
