                                  {orderProfit > 0 ? "+" : ""}
                                  {formatCurrency(orderProfit)}
                                </span>
                                {totalAmount > 0 && (
                                  <span className="text-slate-400">
                                    (Biên LN{" "}
                                    {Math.round(
                                      (orderProfit / totalAmount) * 100
                                    )}
                                    %)
                                  </span>
                                )}
                              </div>
                            )}

                          {/* Progress bar + Đã thu */}
                          {totalAmount > 0 && (
                            <div className="space-y-1">
                              <div
                                className="h-2 w-full rounded-full bg-slate-200 dark:bg-slate-700 overflow-hidden"
