                                <div
                                  className={`h-full rounded-full transition-all duration-300 ${paymentProgress >= 100
                                    ? "bg-gradient-to-r from-emerald-500 to-emerald-600"
                                    : paymentProgress > 0
                                      ? "bg-gradient-to-r from-blue-500 to-blue-600"
                                      : "bg-slate-300"
                                    }`}
