                                  <span className="font-medium text-slate-600 dark:text-slate-300">
                                    Đã thu:
                                  </span>
                                  <span className="font-semibold text-emerald-600 dark:text-emerald-400">
                                    {formatCurrency(Math.max(0, paidAmount))}
                                  </span>
