            setPrintOrder(null);
          }}
          printOrder={printOrder}
          storeSettings={storeSettings || undefined}
          onPrint={handleDoPrint}
        />
        {/* Old inline modal disabled */}


        {/* Repair Templates Modal for Mobile */}
        <RepairTemplatesModal
