export default WorkOrderModal;

import { useMemo } from "react";
import type { WorkOrder, WorkOrderPart, Part } from "../../../types";
import type { ServiceStats } from "../types/service.types";

interface UseServiceStatsOptions {
    workOrders: WorkOrder[];
    dateFilter: "all" | "today" | "week" | "month";
    parts?: Part[]; // Optional parts list for cost lookup fallback
    currentBranchId?: string;
}

interface UseServiceStatsReturn {
    stats: ServiceStats;
    dateFilteredOrders: WorkOrder[];
    totalOpenTickets: number;
    urgentTickets: number;
    urgentRatio: number;
    completionRate: number;
    profitMargin: number;
}

/**
 * Hook to calculate service statistics from work orders
 * 
 * @param options - Work orders, date filter settings, optional parts list, and branch ID
 * @returns Calculated statistics and derived metrics
 */
export function useServiceStats({
    workOrders,
    dateFilter,
    parts = [],
    currentBranchId = ""
}: UseServiceStatsOptions): UseServiceStatsReturn {

    // Create a map for fast part cost lookup
    const partCostMap = useMemo(() => {
        const map = new Map<string, number>();
        parts.forEach((part) => {
            // Priority: costPrice[branch] > costPrice (number) > importPrice > 0
            let cost = 0;
            const p = part as any;

            if (p.costPrice && typeof p.costPrice === 'object' && currentBranchId) {
                cost = p.costPrice[currentBranchId] || 0;
            } else if (typeof p.costPrice === 'number') {
                cost = p.costPrice;
            } else if (p.importPrice && typeof p.importPrice === 'number') {
                cost = p.importPrice; // Handle legacy importPrice field
            }

            if (part.id) map.set(part.id, cost);
            if (part.sku) map.set(part.sku, cost);
        });
        return map;
    }, [parts, currentBranchId]);

    // Helper to get part cost with fallback
    const getPartCost = (partId: string, sku: string, fallbackCost: number) => {
        if (fallbackCost > 0) return fallbackCost;
        return partCostMap.get(partId) || partCostMap.get(sku) || 0;
    };

    // Filter orders by date
    const dateFilteredOrders = useMemo(() => {
        let filtered = [...workOrders];

        if (dateFilter !== "all") {
            const now = new Date();
            const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

            filtered = filtered.filter((o) => {
                const orderDate = new Date(o.creationDate || (o as any).creationdate);

                if (dateFilter === "today") {
                    return orderDate >= today;
                } else if (dateFilter === "week") {
                    const weekAgo = new Date(today);
                    weekAgo.setDate(weekAgo.getDate() - 7);
                    return orderDate >= weekAgo;
                } else if (dateFilter === "month") {
                    const monthAgo = new Date(today);
                    monthAgo.setMonth(monthAgo.getMonth() - 1);
                    return orderDate >= monthAgo;
                }
                return true;
            });
        }

        return filtered;
    }, [workOrders, dateFilter]);

    // Calculate stats
    const stats = useMemo((): ServiceStats => {
        const pending = dateFilteredOrders.filter(
            (o) => o.status === "Tiếp nhận"
        ).length;

        const inProgress = dateFilteredOrders.filter(
            (o) => o.status === "Đang sửa"
        ).length;

        const done = dateFilteredOrders.filter(
            (o) => o.status === "Đã sửa xong"
        ).length;

        const delivered = dateFilteredOrders.filter(
            (o) => o.status === "Trả máy"
        ).length;

        // Calculate realized revenue from paid/partial orders
        const filteredRevenue = dateFilteredOrders
            .filter((o) => o.paymentStatus === "paid" || (o.paymentStatus === "partial" && Number(o.totalPaid || 0) > 0))
            .reduce((sum, o) => {
                const recognizedRevenue = Number(
                    o.paymentStatus === "paid" ? (o.total || 0) : (o.totalPaid || 0)
                );
                return sum + recognizedRevenue;
            }, 0);

        // Calculate recognized profit = recognized revenue - recognized cost
        const filteredProfit = dateFilteredOrders
            .filter((o) => o.paymentStatus === "paid" || (o.paymentStatus === "partial" && Number(o.totalPaid || 0) > 0))
            .reduce((sum, o) => {
                const recognizedRevenue = Number(
                    o.paymentStatus === "paid" ? (o.total || 0) : (o.totalPaid || 0)
                );
                const orderTotal = Number(o.total || 0);
                const recognitionRatio = orderTotal > 0 ? Math.min(1, recognizedRevenue / orderTotal) : 0;

                // Parts cost with fallback lookup
                const partsCost = o.partsUsed?.reduce(
                    (s: number, p: WorkOrderPart) => {
                        const cost = getPartCost(
                            p.partId || (p as any).partid,
                            p.sku || "",
                            p.costPrice || 0
                        );
                        return s + cost * (p.quantity || 1);
                    },
                    0
                ) || 0;

                // Services cost
                const servicesCost = o.additionalServices?.reduce(
                    (s: number, svc: { costPrice?: number; quantity?: number }) =>
                        s + (svc.costPrice || 0) * (svc.quantity || 1),
                    0
                ) || 0;

                const recognizedCost = (partsCost + servicesCost) * recognitionRatio;
                return sum + (recognizedRevenue - recognizedCost);
            }, 0);

        return {
            pending,
            inProgress,
            done,
            delivered,
            filteredRevenue,
            filteredProfit,
        };
    }, [dateFilteredOrders, partCostMap]);

    // Calculate derived metrics
    const totalOpenTickets = stats.pending + stats.inProgress + stats.done;
    const urgentTickets = stats.pending + stats.inProgress;
    const urgentRatio = totalOpenTickets
        ? Math.round((urgentTickets / totalOpenTickets) * 100)
        : 0;
    const completionRate = totalOpenTickets
        ? Math.round((stats.done / totalOpenTickets) * 100)
        : 0;
    const profitMargin = stats.filteredRevenue
        ? Math.round((stats.filteredProfit / stats.filteredRevenue) * 100)
        : 0;

    return {
        stats,
        dateFilteredOrders,
        totalOpenTickets,
        urgentTickets,
        urgentRatio,
        completionRate,
        profitMargin,
    };
}

import React from "react";
import { Share2, Printer, X } from "lucide-react";
import { formatCurrency, formatWorkOrderId } from "../../../utils/format";
import { showToast } from "../../../utils/toast";
import type { WorkOrder, WorkOrderPart } from "../../../types";
import { sanitizeIssueDescriptionForPrint } from "../utils/service.utils";

interface StoreSettings {
  store_name?: string;
  address?: string;
  phone?: string;
  email?: string;
  logo_url?: string;
  bank_qr_url?: string;
  bank_name?: string;
  bank_account_number?: string;
  bank_account_holder?: string;
  bank_branch?: string;
  work_order_prefix?: string;
}

interface PrintOrderPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  printOrder: WorkOrder | null;
  storeSettings?: StoreSettings;
  onPrint: () => void;
}

const cardStyle: React.CSSProperties = {
  border: "1px solid #dbe2ea",
  borderRadius: "3.5mm",
  padding: "3mm",
  marginBottom: "4mm",
  color: "#000",
};

const sectionTitleStyle: React.CSSProperties = {
  fontWeight: "bold",
  marginBottom: "1.5mm",
};

const PrintOrderPreviewModal: React.FC<PrintOrderPreviewModalProps> = ({
  isOpen,
  onClose,
  printOrder,
  storeSettings,
  onPrint,
}) => {
  if (!isOpen || !printOrder) return null;

  const printableIssueDescription = sanitizeIssueDescriptionForPrint(
    printOrder.issueDescription
  );

  const additionalServices = printOrder.additionalServices || [];
  const additionalServicesTotal = additionalServices.reduce(
    (sum: number, service: any) =>
      sum + (service.price || 0) * (service.quantity || 1),
    0
  );

  const handleShare = async () => {
    try {
      showToast.info("Đang tạo hình ảnh...");

      const html2canvas = (await import("html2canvas")).default;
      const element = document.getElementById("mobile-print-preview-content");

      if (!element) {
        showToast.error("Không tìm thấy nội dung phiếu!");
        return;
      }

      const canvas = await html2canvas(element, {
        scale: 2,
        backgroundColor: "#ffffff",
        useCORS: true,
        logging: false,
        width: element.scrollWidth,
        height: element.scrollHeight,
        windowWidth: element.scrollWidth,
        windowHeight: element.scrollHeight,
      });

      const blob = await new Promise<Blob>((resolve) => {
        canvas.toBlob((value) => resolve(value!), "image/png", 1.0);
      });

      const fileName = `Phieu_${formatWorkOrderId(
        printOrder.id,
        storeSettings?.work_order_prefix
      )}.png`;

      if (navigator.share && navigator.canShare) {
        const file = new File([blob], fileName, { type: "image/png" });
        const shareData = { files: [file] };

        if (navigator.canShare(shareData)) {
          await navigator.share(shareData);
          showToast.success("Chia sẻ thành công!");
          return;
        }
      }

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = fileName;
      a.click();
      URL.revokeObjectURL(url);
