                                  <X className="w-4 h-4" />
                                </button>
                              </>
                            ) : (
                              <>
                                {staff.role !== "owner" && (
                                  <button
                                    onClick={() => setEditingStaff({ ...staff })}
                                    className="p-2 text-blue-300 hover:bg-blue-500/10 rounded-xl"
                                    title="Sửa thông tin"
                                  >
                                    <Edit2 className="w-4 h-4" />
                                  </button>
