                              <span className="text-slate-400">Phòng ban</span>
                              <span>{staff.department || "-"}</span>
                            </div>
                            <div className="flex justify-between gap-2">
                              <span className="text-slate-400">Chức vụ</span>
                              <span>{staff.position || "-"}</span>
