                              <div className="pt-2 grid grid-cols-1 gap-2">
                                <button
                                  onClick={() => handleDeleteStaff(staff)}
                                  disabled={savingStaff}
                                  className="px-3 py-2 rounded-lg bg-red-600/20 text-red-300 border border-red-400/30 text-xs font-semibold"
                                >
                                  Xóa
                                </button>
                              </div>
                            )}
                          </div>
                        )}
