                          </th>
                          <th className="text-left py-3 px-3 text-xs font-semibold text-slate-400">
                            Chức vụ
                          </th>
                          <th className="text-left py-3 px-3 text-xs font-semibold text-slate-400">
                            Chi nhánh
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Lương cơ bản
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        {payrollSeedRows.map((row) => (
                          <tr
                            key={row.id}
                            className="border-b border-white/5"
