                            Nhân viên
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Số công việc
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Tiền công được hưởng
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Lương cơ bản
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Thưởng
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
                            Phạt
                          </th>
                          <th className="text-right py-3 px-3 text-xs font-semibold text-slate-400">
