    onClose,
    customerName = "",
    customerPhone = "",
    deviceModel = "",
    imeiSerial = "",
    workOrderId,
}) => {
    const [formData, setFormData] = useState({
        customerName,
        customerPhone,
        deviceModel,
        imeiSerial,
        warrantyPeriodMonths: 3,
