                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                    {/* Customer Info */}
                    <div className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg">
                        <h4 className="text-xs font-bold text-slate-500 uppercase mb-2">
                            Thông tin khách hàng
